package com.wintertodtautopilot;

/** Rate limiting and attention episodes, independent of rendering and wall-clock time. */
public final class WintertodtAttentionTracker
{
    private int lastAttentionNotification = -1000;
    private int lastWarmthNotification = -1000;
    private boolean lowNotified;
    private boolean startNotified;
    private boolean attentionNotified;
    private RoundState lastRound = RoundState.OUTSIDE;
    private int lastPoints = -1;
    private boolean rewardPending;
    private boolean rewardNotified;

    public void reset()
    {
        lastAttentionNotification = -1000; lastWarmthNotification = -1000;
        lowNotified = false; startNotified = false;
        attentionNotified = false; lastRound = RoundState.OUTSIDE;
        lastPoints = -1; rewardPending = false; rewardNotified = false;
    }
    public String notification(WintertodtSnapshot s, WintertodtObjective objective,
        WintertodtAutopilotConfig config, int tick)
    {
        if (s.getRoundState() == RoundState.OUTSIDE || s.getRoundState() == RoundState.LOBBY)
        { reset(); return null; }
        boolean newCountdown = s.getRoundState() == RoundState.COUNTDOWN && lastRound != RoundState.COUNTDOWN;
        boolean newActive = s.active() && lastRound != RoundState.ACTIVE && lastRound != RoundState.ENDING;
        if (newCountdown || newActive)
        {
            lastPoints = -1; rewardPending = false; rewardNotified = false;
            attentionNotified = false;
        }
        if (s.active() || s.getRoundState() == RoundState.COMPLETE)
        {
            if (lastPoints >= 0 && lastPoints < 500 && s.getPoints() >= 500 && !rewardNotified
                && config.notifyRewardSecured()) { rewardPending = true; }
            if (s.getPoints() >= 0) { lastPoints = s.getPoints(); }
        }
        boolean low = (s.active() || objective.getType() == ObjectiveType.RESTORE_WARMTH) && s.getWarmth() >= 0
            && s.getWarmth() <= Math.min(config.emergencyWarmth(), config.restoreWarmth())
            && s.getCurrentActivity() != PlayerActivity.RESTORING_WARMTH;
        if (!low) { lowNotified = false; }
        if (newCountdown) { startNotified = false; }
        lastRound = s.getRoundState();
        if (!s.isPlayerIdle() || !objective.actionable()) { attentionNotified = false; }
        String message = null;
        if (low && !lowNotified && config.notifyLowWarmth() && tick - lastWarmthNotification >= 50)
        {
            lowNotified = true; lastWarmthNotification = tick;
            message = "Wintertodt: low warmth - restore now";
        }
        else if (config.notifyRoundStart() && !startNotified && s.getRoundState() == RoundState.COUNTDOWN
            && s.getSecondsToStart() > 0 && s.getSecondsToStart() <= 5)
        {
            startNotified = true; message = "Wintertodt round starts in " + s.getSecondsToStart() + " seconds";
        }
        else if (rewardPending && config.notifyRewardSecured() && !low)
        {
            rewardPending = false; rewardNotified = true;
            message = "Wintertodt: 500 points secured - reward minimum reached";
        }
        else if (s.isPlayerIdle() && objective.actionable() && !attentionNotified
            && tick - lastAttentionNotification >= 50
            && s.getInactiveTicks() * 0.6 >= config.inactivitySeconds())
        {
            boolean important = objective.getType() == ObjectiveType.REPAIR || objective.getType() == ObjectiveType.LIGHT
                || objective.getType() == ObjectiveType.HEAL_PYROMANCER || objective.getType() == ObjectiveType.MAKE_REJUVENATION;
            if (config.notifyIdle() || config.notifyStateChange() && important)
            {
                attentionNotified = true; lastAttentionNotification = tick;
                message = "Wintertodt: " + objective.getInstruction();
            }
        }
        return message;
    }
}

package com.wintertodtautopilot;

import net.runelite.client.config.*;

@ConfigGroup("wintertodtautopilot")
public interface WintertodtAutopilotConfig extends Config
{
    @ConfigSection(name = "Your plan", description = "Choose your mode and shared preferences.", position = 0)
    String plan = "plan";
    @ConfigSection(name = "Mass settings", description = "Strategy and reward goal for mass worlds. Used only in Mass mode.", position = 1)
    String mass = "mass";
    @ConfigSection(name = "Solo settings (experimental)", description = "Strategy, point goal and finishing controls. Used only in Solo mode.", position = 2, closedByDefault = true)
    String solo = "solo";
    @ConfigSection(name = "Warmth", description = "Optional recovery thresholds. The defaults suit mass worlds.", position = 3, closedByDefault = true)
    String warmth = "warmth";
    @ConfigSection(name = "On-screen guidance", description = "Choose how much help appears in the game", position = 4)
    String guidance = "guidance";
    @ConfigSection(name = "Notifications", description = "Attention alerts", position = 5, closedByDefault = true)
    String notifications = "notifications";
    @ConfigSection(name = "Advanced", description = "Diagnostics for live validation", position = 6, closedByDefault = true)
    String advanced = "advanced";

    @ConfigItem(position = -1, keyName = "pauseGuidance", name = "Pause guidance",
        description = "Pause all guidance and notifications, including warmth warnings. Uncheck to resume. This choice is saved.", section = plan)
    default boolean pauseGuidance() { return false; }

    @ConfigItem(position = -2, keyName = "mode", name = "Mode",
        description = "Mass or experimental Solo guidance. Solo assumes you chose an empty world; it cannot guarantee exclusive control.", section = plan)
    default WintertodtMode mode() { return WintertodtMode.MASS; }

    @ConfigItem(position = 0, keyName = "soloStrategy", name = "Solo strategy",
        description = "Points / Rewards fletches roots. Firemaking XP feeds roots. Fletch roots can override either choice.", section = solo)
    default SoloStrategy soloStrategy() { return SoloStrategy.POINTS; }

    @ConfigItem(position = 1, keyName = "soloPointGoal", name = "Solo point goal",
        description = "Solo finishes when this many points are earned. Carried fuel must be fed first. This is a score target, not a reward-cap estimate.", section = solo)
    @Range(min = 500, max = 100000)
    default int soloPointGoal() { return 5000; }

    @ConfigItem(position = 2, keyName = "finishSoloRound", name = "Finish this Solo round",
        description = "Finish the current Solo round early. Once requested, it stays active until the round ends, you change mode or hop worlds.", section = solo)
    default boolean finishSoloRound() { return false; }

    @ConfigItem(position = 0, keyName = "strategy", name = "Strategy", description = "Mass strategy. Balanced: all-round play. Firemaking XP: feed roots. Points / Rewards: more kindling. Low Attention: fewer task changes.", section = mass)
    default WintertodtStrategy strategy() { return WintertodtStrategy.MASS_BALANCED; }

    @ConfigItem(position = 1, keyName = "workingCorner", name = "Working brazier", description = "Automatic follows your nearby working corner in Mass and Solo, with a margin to prevent switching back and forth. Choose a brazier only to stay at a specific corner.", section = plan)
    default WorkingCorner workingCorner() { return WorkingCorner.AUTOMATIC; }

    @ConfigItem(position = 2, keyName = "pointGoal", name = "Reward goal", description = "500 points secures a reward. Guidance continues toward the next threshold after reaching your goal; carried fuel must be fed to count.", section = mass)
    default PointGoal pointGoal() { return PointGoal.MINIMUM_500; }

    @ConfigItem(position = 3, keyName = "fletchMode", name = "Fletch roots", description = "Leave Automatic selected to let your strategy decide. Always and Never override it; urgent feeding can still take priority.", section = plan)
    default FletchMode fletchMode() { return FletchMode.AUTOMATIC; }

    @ConfigItem(position = 4, keyName = "warmthWarning", name = "Warmth warning", description = "Color the warmth display below this percentage", section = warmth)
    @Range(min = 1, max = 100)
    default int warmthWarning() { return 50; }

    @ConfigItem(position = 5, keyName = "restoreWarmth", name = "Restore warmth at", description = "Interrupt routine actions below this percentage", section = warmth)
    @Range(min = 1, max = 100)
    default int restoreWarmth() { return 50; }

    @ConfigItem(position = 6, keyName = "emergencyWarmth", name = "Emergency warmth at", description = "Strong warning below this percentage", section = warmth)
    @Range(min = 1, max = 100)
    default int emergencyWarmth() { return 20; }

    @ConfigItem(position = 9, keyName = "highlightTarget", name = "Highlight current objective", description = "Outline the single scene target", section = guidance)
    default boolean highlightTarget() { return true; }

    @ConfigItem(position = 10, keyName = "highlightInventory", name = "Highlight inventory items", description = "Outline items needed for the current action", section = guidance)
    default boolean highlightInventory() { return true; }

    @ConfigItem(position = 11, keyName = "showHintArrow", name = "Show hint arrow", description = "Show an arrow when another plugin or the game has no active arrow", section = guidance)
    default boolean showHintArrow() { return true; }

    @ConfigItem(position = 12, keyName = "showPath", name = "Show walking path", description = "Draw a route to the current target. Solo can use the northern gap at 60 Agility; you click each jump yourself.", section = guidance)
    default boolean showPath() { return false; }

    @ConfigItem(position = 7, keyName = "showOverlay", name = "Show main overlay", description = "Movable next-action panel", section = guidance)
    default boolean showOverlay() { return true; }

    @ConfigItem(position = 8, keyName = "overlayDetail", name = "Overlay detail", description = "Minimal: action and safety. Normal: adds a short explanation and finish estimate. Detailed: adds supplies and planning estimates.", section = guidance)
    default OverlayDetail overlayDetail() { return OverlayDetail.NORMAL; }

    @ConfigItem(position = 20, keyName = "notifyIdle", name = "Notify on idle", description = "Notify once per attention episode after the inactivity delay", section = notifications)
    default boolean notifyIdle() { return false; }

    @ConfigItem(position = 21, keyName = "notifyLowWarmth", name = "Notify low warmth", description = "Notify once per emergency warmth episode, with its own 30-second cooldown. Other alerts never delay this warning.", section = notifications)
    default boolean notifyLowWarmth() { return true; }

    @ConfigItem(position = 22, keyName = "notifyRoundStart", name = "Notify round start", description = "Notify when a round starts in five seconds", section = notifications)
    default boolean notifyRoundStart() { return false; }

    @ConfigItem(position = 23, keyName = "notifyStateChange", name = "Notify important changes", description = "Notify about broken braziers and downed pyromancers after inactivity", section = notifications)
    default boolean notifyStateChange() { return false; }

    @ConfigItem(position = 25, keyName = "notifyRewardSecured", name = "Notify reward secured",
        description = "Notify once when earned points reach 500 this round. Carried fuel does not count. Pausing guidance pauses this alert too.", section = notifications)
    default boolean notifyRewardSecured() { return false; }

    @ConfigItem(position = 24, keyName = "inactivitySeconds", name = "Attention delay", description = "Seconds without meaningful action before attention notifications", section = notifications)
    @Range(min = 1, max = 60)
    default int inactivitySeconds() { return 6; }

    @ConfigItem(position = 30, keyName = "debug", name = "Debug overlay and logs", description = "Show observed state, log objective changes and per-tick corner observation traces", section = advanced)
    default boolean debug() { return false; }

    @ConfigItem(position = 13, keyName = "highlightStandingTiles", name = "Highlight standing tiles", description = "Optional floor marker for the destination; off by default.", section = guidance)
    default boolean highlightStandingTiles() { return false; }

    @ConfigItem(position = 14, keyName = "pulseInterruptions", name = "Pulse attention cues", description = "Pulse borders for stopped actions, repairs, relighting, low warmth and urgent feeding", section = guidance)
    default boolean pulseInterruptions() { return true; }

    @ConfigItem(position = 15, keyName = "highlightBorderWidth", name = "Highlight border width",
        description = "Border width in pixels for scene targets and inventory items. Attention pulses change opacity, not width.", section = guidance)
    @Range(min = 1, max = 4)
    default int highlightBorderWidth() { return 1; }

}

package com.wintertodtautopilot;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.events.ConfigChanged;

@PluginDescriptor(name = "Wintertodt Autopilot",
    description = "Shows your next Wintertodt action, highlights what you need, and helps plan warmth and points. You do the clicking.",
    tags = {"wintertodt", "wt", "firemaking", "fm", "woodcutting", "fletching", "skilling", "minigame",
        "helper", "guide", "brazier", "bruma", "warmth", "points", "rewards", "mass", "solo"})
@Slf4j
public class WintertodtAutopilotPlugin extends Plugin
{
    static final String UPDATE_NOTICE_VERSION = "0.2.1";
    static final String UPDATE_NOTICE_KEY = "lastUpdateNotice";
    static final String UPDATE_NOTICE = "Wintertodt Autopilot 0.2.1: fletching knife support, better alerts, reward milestone feedback, and separate Mass/Solo settings.";
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private WintertodtAutopilotConfig config;
    @Inject private WintertodtStateTracker tracker;
    @Inject private WintertodtObjectTracker objects;
    @Inject private WintertodtNpcTracker npcs;
    @Inject private WintertodtHintArrow arrow;
    @Inject private WintertodtPathTracker paths;
    @Inject private OverlayManager overlays;
    @Inject private WintertodtOverlay panel;
    @Inject private WintertodtSceneOverlay scene;
    @Inject private WintertodtInventoryOverlay inventory;
    @Inject private Notifier notifier;
    public boolean isPaused() { return config.pauseGuidance(); }
    private final WintertodtDecisionEngine engine = new WintertodtDecisionEngine();
    private final WintertodtSoloEngine solo = new WintertodtSoloEngine();
    public SoloPhase getSoloPhase() { return solo.getPhase(); }
    public String getSoloEnergyTrend() { return solo.getEnergyTrend(); }
    public boolean isSoloFinishRequested() { return solo.isFinishRequested(); }
    private final WintertodtAttentionTracker attention = new WintertodtAttentionTracker();
    @Getter private WintertodtSnapshot snapshot = WintertodtSnapshot.builder().build();
    @Getter private WintertodtObjective objective;
    @Getter private TileObject targetObject;
    @Getter private NPC targetNpc;
    @Getter private WorldPoint targetPoint;
    @Getter private int potionTargetDoses;
    public java.util.List<WorldPoint> getPath() { return paths.getPath(); }
    private boolean bootstrapNeeded = true;

    @Provides
    WintertodtAutopilotConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(WintertodtAutopilotConfig.class);
    }
    @Override
    protected void startUp() throws Exception
    {
        overlays.add(panel); overlays.add(scene); overlays.add(inventory);
        clientThread.invoke(this::reset);
    }
    @Override
    protected void shutDown() throws Exception
    {
        overlays.remove(panel); overlays.remove(scene); overlays.remove(inventory);
        clientThread.invoke(this::reset);
    }
    private void reset()
    {
        arrow.clear(); paths.reset(); potionTargetDoses = 0; tracker.reset(); objects.reset(); npcs.reset(); engine.reset(); solo.reset(); attention.reset();
        snapshot = WintertodtSnapshot.builder().build(); objective = null;
        targetObject = null; targetNpc = null; targetPoint = null; bootstrapNeeded = true;
    }
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOADING:
            case CONNECTION_LOST:
                boolean finishIntent = solo.isFinishRequested();
                reset();
                if (finishIntent) { solo.configure(config.soloPointGoal(), true); }
                break;
            case HOPPING:
            case LOGIN_SCREEN:
                reset();
                if (config.finishSoloRound())
                { configManager.setConfiguration("wintertodtautopilot", "finishSoloRound", false); }
                break;
            default: break;
        }
    }
    private void showUpdateNotice()
    {
        // Run anywhere after login, including for players who have paused gameplay guidance.
        if (UPDATE_NOTICE_VERSION.equals(configManager.getConfiguration("wintertodtautopilot", UPDATE_NOTICE_KEY)))
        { return; }
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", UPDATE_NOTICE, null);
        configManager.setConfiguration("wintertodtautopilot", UPDATE_NOTICE_KEY, UPDATE_NOTICE_VERSION);
    }
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN) { return; }
        showUpdateNotice();
        Player player = client.getLocalPlayer();
        boolean inRegion = player != null && player.getWorldLocation().getRegionID() == WintertodtConstants.REGION;
        if (!inRegion)
        {
            if (snapshot.getRoundState() != RoundState.OUTSIDE) { reset(); }
            return;
        }
        if (bootstrapNeeded)
        {
            objects.bootstrap();
            for (NPC npc : client.getTopLevelWorldView().npcs()) { npcs.add(npc); }
            bootstrapNeeded = false;
        }
        boolean soloMode = config.mode() == WintertodtMode.SOLO;
        WintertodtSnapshot next = tracker.snapshot(config.workingCorner());
        if (snapshot.active() != next.active()) { engine.reset(); }
        boolean verifiedBoundary = next.getRoundState() == RoundState.COMPLETE
            || next.getRoundState() == RoundState.COUNTDOWN && next.getSecondsToStart() > 0
            || next.active() && snapshot.getRoundState() == RoundState.COUNTDOWN && snapshot.getSecondsToStart() > 0;
        if (soloMode && verifiedBoundary && config.finishSoloRound())
        { configManager.setConfiguration("wintertodtautopilot", "finishSoloRound", false); }
        solo.configure(config.soloPointGoal(), soloMode && !verifiedBoundary && next.active() && config.finishSoloRound());
        WintertodtPlanner planner = soloMode ? solo : engine;
        WintertodtObjective chosen = planner.decide(next, PlannerSettings.from(config));
        if (config.debug() && (objective == null || objective.getType() != chosen.getType()
            || !objective.getReason().equals(chosen.getReason())))
        {
            log.debug("{} -> {} reason={}", objective == null ? "NONE" : objective.getType(), chosen.getType(), chosen.getReason());
        }
        if (config.debug()) { log.debug("{}", WintertodtObservationTrace.format(next, chosen, config.mode(), soloMode ? solo.getPhase() : null,
            solo.getEnergyTrend(), solo.getTransitionReason(), solo.isFinishRequested())); }
        snapshot = next; objective = chosen;
        potionTargetDoses = planner.getPreparationDoseTarget();
        if (isPaused())
        {
            clearGuidance();
            return;
        }
        resolveTarget();
        boolean needsCue = !WintertodtGuidance.performing(snapshot, objective);
        paths.update(targetPoint, targetObject, targetNpc, needsCue && (config.showPath() || config.highlightStandingTiles()));
        arrow.update(targetNpc, targetPoint, needsCue && config.showHintArrow());
        String message = attention.notification(snapshot, objective, config, client.getTickCount());
        if (message != null) { notifier.notify(message); }
    }
    private void clearGuidance()
    {
        arrow.clear(); paths.reset();
        targetObject = null; targetNpc = null; targetPoint = null;
    }
    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if ("wintertodtautopilot".equals(event.getGroup()))
        {
            clientThread.invoke(() -> {
                if ("pauseGuidance".equals(event.getKey()))
                {
                    attention.reset();
                    if (isPaused()) { clearGuidance(); }
                    else { engine.reset(); }
                }
                else if ("mode".equals(event.getKey()))
                {
                    engine.reset(); solo.reset(); clearGuidance();
                    if (config.finishSoloRound())
                    { configManager.setConfiguration("wintertodtautopilot", "finishSoloRound", false); }
                }
                else if ("soloPointGoal".equals(event.getKey()) || "finishSoloRound".equals(event.getKey()))
                { clearGuidance(); }
                else if ("soloStrategy".equals(event.getKey()) || "strategy".equals(event.getKey()) || "pointGoal".equals(event.getKey())
                    || "fletchMode".equals(event.getKey()) || "workingCorner".equals(event.getKey()))
                {
                    engine.reset();
                    clearGuidance();
                }
                // Apply visual settings immediately, even between game ticks.
                if (!config.showHintArrow()) { arrow.clear(); }
                if (!config.showPath() && !config.highlightStandingTiles()) { paths.reset(); }
            });
        }
    }
    private void resolveTarget()
    {
        targetObject = null; targetNpc = null; targetPoint = null;
        TargetKind target = objective.getTarget();
        WorkingCorner destination = objective.getDestination() == WorkingCorner.AUTOMATIC
            ? snapshot.getWorkingCorner() : objective.getDestination();
        if (target == TargetKind.NONE) { return; }
        if (target == TargetKind.PYROMANCER || target == TargetKind.BREWMA)
        {
            targetNpc = npcs.target(target, target == TargetKind.PYROMANCER
                ? destination.location() : snapshot.getPlayerLocation());
            if (targetNpc != null) { targetPoint = targetNpc.getWorldLocation(); }
        }
        else
        {
            targetObject = objective.getDestination() == WorkingCorner.AUTOMATIC
                ? objects.target(target, snapshot.getPlayerLocation())
                : objects.target(target, snapshot.getPlayerLocation(), destination);
            if (targetObject != null) { targetPoint = targetObject.getWorldLocation(); }
        }
        if (targetPoint == null && (target == TargetKind.BRAZIER || target == TargetKind.PYROMANCER))
        {
            targetPoint = destination.location();
        }
    }
    @Subscribe public void onAnimationChanged(AnimationChanged e) { tracker.animation(e.getActor()); }
    @Subscribe public void onChatMessage(ChatMessage e) { tracker.chat(e); }
    @Subscribe public void onMenuOptionClicked(MenuOptionClicked e) { tracker.clicked(e); }
    @Subscribe public void onGameObjectSpawned(GameObjectSpawned e) { paths.invalidate(); objects.add(e.getGameObject()); }
    @Subscribe public void onGameObjectDespawned(GameObjectDespawned e) { removed(e.getGameObject()); }
    @Subscribe public void onWallObjectSpawned(WallObjectSpawned e) { paths.invalidate(); objects.add(e.getWallObject()); }
    @Subscribe public void onWallObjectDespawned(WallObjectDespawned e) { removed(e.getWallObject()); }
    @Subscribe public void onDecorativeObjectSpawned(DecorativeObjectSpawned e) { paths.invalidate(); objects.add(e.getDecorativeObject()); }
    @Subscribe public void onDecorativeObjectDespawned(DecorativeObjectDespawned e) { removed(e.getDecorativeObject()); }
    @Subscribe public void onGroundObjectSpawned(GroundObjectSpawned e) { paths.invalidate(); objects.add(e.getGroundObject()); }
    @Subscribe public void onGroundObjectDespawned(GroundObjectDespawned e) { removed(e.getGroundObject()); }
    private void removed(TileObject object)
    {
        paths.invalidate(); objects.remove(object);
        if (targetObject == object) { targetObject = null; arrow.clear(); }
    }
    @Subscribe public void onNpcSpawned(NpcSpawned e) { npcs.add(e.getNpc()); }
    @Subscribe public void onNpcChanged(NpcChanged e) { npcs.remove(e.getNpc()); npcs.add(e.getNpc()); }
    @Subscribe public void onNpcDespawned(NpcDespawned e)
    {
        npcs.remove(e.getNpc());
        if (targetNpc == e.getNpc()) { targetNpc = null; arrow.clear(); }
    }
}

package com.wintertodtautopilot;

import java.awt.Rectangle;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Resolve compass positions from the current HUD layout, never legacy child offsets. */
final class WintertodtBrazierHud
{
    private static final int[] WIDGETS = {InterfaceID.WintStatus.BRAZIER1, InterfaceID.WintStatus.BRAZIER2,
        InterfaceID.WintStatus.BRAZIER3, InterfaceID.WintStatus.BRAZIER4};
    private WintertodtBrazierHud() { }

    static Map<WorkingCorner, BrazierState> read(Client client)
    {
        Map<WorkingCorner, BrazierState> result = new EnumMap<>(WorkingCorner.class);
        if (client == null) { return result; }
        Widget[] widgets = new Widget[4];
        Rectangle[] bounds = new Rectangle[4];
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, minY = minX, maxY = maxX;
        for (int i = 0; i < 4; i++)
        {
            widgets[i] = client.getWidget(WIDGETS[i]);
            if (widgets[i] == null || widgets[i].isHidden()) { return result; }
            bounds[i] = widgets[i].getBounds();
            if (bounds[i] == null || bounds[i].width <= 0 || bounds[i].height <= 0) { return result; }
            int x = (int) bounds[i].getCenterX(), y = (int) bounds[i].getCenterY();
            minX = Math.min(minX, x); maxX = Math.max(maxX, x);
            minY = Math.min(minY, y); maxY = Math.max(maxY, y);
        }
        if (maxX - minX < 10 || maxY - minY < 10) { return result; }
        for (int i = 0; i < 4; i++)
        {
            boolean west = bounds[i].getCenterX() < (minX + maxX) / 2.0;
            boolean north = bounds[i].getCenterY() < (minY + maxY) / 2.0;
            WorkingCorner corner = north ? (west ? WorkingCorner.NORTHWEST : WorkingCorner.NORTHEAST)
                : (west ? WorkingCorner.SOUTHWEST : WorkingCorner.SOUTHEAST);
            if (result.containsKey(corner)) { result.clear(); return result; }
            result.put(corner, decode(widgets[i].getSpriteId()));
        }
        return result;
    }
    static BrazierState decode(int sprite)
    {
        // Sprite semantics checked against the pinned Solo Helper source; layout is read at runtime.
        switch (sprite)
        {
            case 1397: return BrazierState.BROKEN;
            case 1398: return BrazierState.UNLIT;
            case 1399: return BrazierState.LIT;
            default: return BrazierState.UNKNOWN;
        }
    }
}

