package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import net.runelite.api.NPC;

/** Read-only foundation for Solo. Scene observations take precedence; HUD compass positions provide remote coverage. */
public final class WintertodtCornerTracker
{
    private final EnumMap<WorkingCorner, CornerObservation> previous = new EnumMap<>(WorkingCorner.class);
    private int lastTick = -1;

    public void reset() { previous.clear(); lastTick = -1; }

    public List<CornerObservation> observe(int tick, WintertodtObjectTracker objects, WintertodtNpcTracker npcs)
    {
        return observe(tick, objects, npcs, null);
    }

    public List<CornerObservation> observe(int tick, WintertodtObjectTracker objects,
        WintertodtNpcTracker npcs, net.runelite.api.Client client)
    {
        if (tick < lastTick) { reset(); }
        lastTick = tick;
        java.util.Map<WorkingCorner, BrazierState> hud = WintertodtBrazierHud.read(client);
        java.util.Map<WorkingCorner, BrazierState> scene = new EnumMap<>(WorkingCorner.class);
        boolean conflict = false;
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c == WorkingCorner.AUTOMATIC) { continue; }
            BrazierState state = objects.brazierAt(c);
            if (state == null) { state = BrazierState.UNKNOWN; }
            scene.put(c, state);
            BrazierState remote = hud.get(c);
            if (state != BrazierState.UNKNOWN && state != BrazierState.UNAVAILABLE
                && remote != null && remote != BrazierState.UNKNOWN && state != remote) { conflict = true; }
        }
        // A mismatch may be a redraw delay or a changed HUD. Do not trust remote readings that tick.
        if (conflict) { hud.clear(); }
        List<CornerObservation> result = new ArrayList<>(4);
        for (WorkingCorner corner : WorkingCorner.values())
        {
            if (corner == WorkingCorner.AUTOMATIC) { continue; }
            CornerObservation old = previous.get(corner);
            BrazierState brazier = scene.get(corner);
            boolean brazierVisible = brazier != BrazierState.UNKNOWN && brazier != BrazierState.UNAVAILABLE;
            CornerObservation.Source source = brazierVisible ? CornerObservation.Source.DIRECT_SCENE : CornerObservation.Source.NONE;
            if (!brazierVisible && hud.getOrDefault(corner, BrazierState.UNKNOWN) != BrazierState.UNKNOWN)
            { brazier = hud.get(corner); source = CornerObservation.Source.HUD_WIDGET; }
            boolean brazierKnown = source != CornerObservation.Source.NONE;
            NPC npc = npcs.target(TargetKind.PYROMANCER, corner.location());
            int id = npc == null ? -1 : WintertodtNpcTracker.id(npc);
            CornerObservation.PyromancerState pyro = id == net.runelite.api.gameval.NpcID.WINT_WIZARD
                ? CornerObservation.PyromancerState.ALIVE : id == net.runelite.api.gameval.NpcID.WINT_WIZARD_DOWN
                ? CornerObservation.PyromancerState.INCAPACITATED : CornerObservation.PyromancerState.UNKNOWN;
            boolean pyroVisible = pyro != CornerObservation.PyromancerState.UNKNOWN;
            int health = -1;
            if (pyro == CornerObservation.PyromancerState.INCAPACITATED) { health = 0; }
            else if (pyroVisible && npc.getHealthScale() > 0 && npc.getHealthRatio() >= 0
                && npc.getHealthRatio() <= npc.getHealthScale())
            {
                health = npc.getHealthRatio() * 100 / npc.getHealthScale();
            }
            CornerObservation observation = new CornerObservation(corner,
                brazierKnown ? brazier : BrazierState.UNKNOWN, pyro, health,
                source,
                pyroVisible ? CornerObservation.Source.DIRECT_SCENE : CornerObservation.Source.NONE,
                brazierKnown ? tick : old == null ? -1 : old.getBrazierObservedTick(),
                pyroVisible ? tick : old == null ? -1 : old.getPyromancerObservedTick(),
                brazierVisible, pyroVisible);
            previous.put(corner, observation);
            result.add(observation);
        }
        return Collections.unmodifiableList(result);
    }
}

package com.wintertodtautopilot;

import net.runelite.api.gameval.ItemID;

/** Deterministic tick planner. Emergency objectives never overwrite the normal batch. */
public final class WintertodtDecisionEngine implements WintertodtPlanner
{
    private ObjectiveType normal;
    private int batchTarget;
    private int kindlingTarget;
    private WorkingCorner corner;
    private PlannerSettings previousSettings;
    private boolean suppliesReady;
    private int preparationDoseTarget;
    private boolean finishing;
    private boolean finishComplete;

    public int getPreparationDoseTarget() { return preparationDoseTarget; }

    public void reset()
    {
        normal = null;
        batchTarget = 0;
        kindlingTarget = 0;
        corner = null;
        previousSettings = null;
        suppliesReady = false;
        preparationDoseTarget = 0;
        finishing = false;
        finishComplete = false;
    }

    public WintertodtObjective decide(WintertodtSnapshot s, PlannerSettings settings)
    {
        if (!settings.equals(previousSettings))
        {
            reset();
            previousSettings = settings;
        }
        if (corner != s.getWorkingCorner())
        {
            normal = null;
            corner = s.getWorkingCorner();
            finishing = false;
            finishComplete = false;
        }
        WintertodtObjective safety = WintertodtSafety.objective(s, settings);
        if (safety != null) { return safety; }

        if (!s.active())
        {
            normal = null;
            finishing = false;
            finishComplete = false;
            if (s.getRoundState() == RoundState.OUTSIDE)
            {
                return action(ObjectiveType.WAIT, "Waiting for Wintertodt", "outside", TargetKind.NONE);
            }
            if (s.getRoundState() == RoundState.LOBBY)
            {
                return action(ObjectiveType.ENTER, "Enter the Wintertodt prison", "lobby", TargetKind.DOOR);
            }
            WintertodtObjective preparation = prepare(s, settings);
            if (preparation != null) { return preparation; }
            if (s.getRoundState() == RoundState.COMPLETE)
            {
                return action(ObjectiveType.ROUND_COMPLETE, "Round complete", "round_complete", TargetKind.NONE);
            }
            if (s.getSecondsToStart() >= 0 && s.getSecondsToStart() <= 15)
            {
                return action(ObjectiveType.POSITION, "Get ready at your brazier", "countdown_position", TargetKind.BRAZIER);
            }
            return action(ObjectiveType.WAIT, "Wait for the round", "countdown", TargetKind.NONE);
        }

        int goal = WintertodtGuidance.rewardTarget(settings.getPointGoal(), s.getPoints());
        boolean timed = s.getRoundBudgetSeconds() >= 0;
        boolean ending = finishing || (timed ? additionalRoots(s, settings, goal) == 0 : s.getEndUrgency() != EndUrgency.NORMAL);
        int usefulBatch = minimumBatch(s, settings, goal);
        if (s.getBrumaRoots() + s.getBrumaKindling() == 0 && finishComplete
            && ((!timed && settings.getStrategy() != WintertodtStrategy.MASS_XP)
                || (timed && additionalRoots(s, settings, goal) < usefulBatch)))
        {
            return action(ObjectiveType.WAIT, "Final fuel fed - wait for the next round", "finish_wait", TargetKind.NONE);
        }
        if (timed && s.getBrumaRoots() + s.getBrumaKindling() == 0
            && additionalRoots(s, settings, goal) < usefulBatch)
        {
            return action(ObjectiveType.WAIT, "Round ending - no time for another root", "finish_wait", TargetKind.NONE);
        }
        if ((!timed && s.getEndUrgency() == EndUrgency.IMMINENT || timed && s.getRoundBudgetSeconds() < 6) && s.getBrumaRoots() + s.getBrumaKindling() == 0
            && s.rewardThresholdReached())
        {
            return action(ObjectiveType.WAIT, "Round ending - rewards secured", "ending_secured", TargetKind.NONE);
        }
        // Cold does not stop chopping. Keep the resource batch ahead of distant maintenance.
        if (s.getCurrentActivity() == PlayerActivity.CHOPPING && !ending
            && !finishing && (!timed || additionalRoots(s, settings, goal) > 0))
        {
            return normal(s, settings, goal);
        }
        if (s.getLocalBrazierState() == BrazierState.BROKEN)
        {
            if (!s.isHasHammer())
            {
                return tool(TargetKind.HAMMER_CRATE, "missing_hammer");
            }
            return new WintertodtObjective(ObjectiveType.REPAIR, "Repair the brazier", "brazier_broken",
                TargetKind.BRAZIER, 0, true, ItemID.HAMMER);
        }
        if (s.isLocalPyromancerKnown() && s.isLocalPyromancerIncapacitated()
            && (s.getLocalBrazierState() == BrazierState.UNLIT || !ending))
        {
            if (s.getRejuvenationDoses() > 0)
            {
                return new WintertodtObjective(ObjectiveType.HEAL_PYROMANCER, "Heal the pyromancer",
                    "local_pyromancer_down", TargetKind.PYROMANCER, 1, false, s.getPotionItem());
            }
            // Do not make long potion trips while other mass-world players can heal near the end.
            if (!ending) { return potion(s, 1, "heal_supply"); }
            if (s.getLocalBrazierState() == BrazierState.UNLIT)
            {
                return action(ObjectiveType.WAIT, "Wait for the local pyromancer to be healed",
                    "ending_pyromancer_blocked", TargetKind.PYROMANCER);
            }
        }

        if (s.getLocalBrazierState() == BrazierState.UNKNOWN
            || s.getLocalBrazierState() == BrazierState.UNAVAILABLE)
        {
            return action(ObjectiveType.POSITION, "Move to your working brazier", "brazier_unobserved", TargetKind.BRAZIER);
        }
        if (s.getLocalBrazierState() == BrazierState.UNLIT)
        {
            if (!s.isLocalPyromancerKnown())
            {
                return action(ObjectiveType.POSITION, "Move closer to your pyromancer", "pyromancer_unobserved", TargetKind.BRAZIER);
            }
            if (!s.isHasTinderbox() && !s.isHasBrumaTorch())
            {
                return tool(TargetKind.TINDERBOX_CRATE, "missing_tinderbox");
            }
            return new WintertodtObjective(ObjectiveType.LIGHT, "Relight the brazier", "brazier_unlit",
                TargetKind.BRAZIER, 0, false, ItemID.TINDERBOX, ItemID.WINT_TORCH, ItemID.WINT_TORCH_OFFHAND);
        }
        WintertodtObjective preparation = ending && s.getLocalBrazierState() == BrazierState.LIT
            && (s.getBrumaRoots() + s.getBrumaKindling() > 0 || finishing || finishComplete) ? null : prepare(s, settings);
        if (preparation != null) { return preparation; }

        WintertodtObjective deadline = finish(s, settings, goal);
        if (deadline != null) { return deadline; }
        if (ending && !timed)
        {
            if (s.getBrumaKindling() + s.getBrumaRoots() > 0)
            {
                return feed(s, s.rewardThresholdReached() ? "round_ending" : "ending_secure_500", true);
            }
            if (s.getEndUrgency() == EndUrgency.IMMINENT)
            {
                return action(ObjectiveType.WAIT, "Round ending - no fuel remaining", "ending_no_fuel", TargetKind.NONE);
            }
        }
        return normal(s, settings, goal);
    }

    private WintertodtObjective normal(WintertodtSnapshot s, PlannerSettings settings, int goal)
    {
        int materials = s.getBrumaRoots() + s.getBrumaKindling();
        boolean fletch = settings.fletch(s) && (s.getRoundBudgetSeconds() >= 0 || s.getEndUrgency() == EndUrgency.NORMAL);
        if (normal == ObjectiveType.FLETCH && (!fletch || s.getBrumaRoots() == 0 || s.getBrumaKindling() >= kindlingTarget))
        {
            normal = ObjectiveType.FEED;
        }
        if (normal == ObjectiveType.FEED && materials == 0) { normal = null; }
        if (normal == ObjectiveType.CHOP && (materials >= batchTarget || s.getFreeSlots() == 0))
        {
            if (fletch && s.getBrumaRoots() > 0)
            {
                normal = ObjectiveType.FLETCH;
                int needed = upgrades(s, settings, goal);
                kindlingTarget = s.getBrumaKindling() + Math.min(s.getBrumaRoots(), needed);
                if (kindlingTarget == s.getBrumaKindling()) { normal = ObjectiveType.FEED; }
            }
            else { normal = materials > 0 ? ObjectiveType.FEED : null; }
        }
        if (normal == null)
        {
            int projected = s.getPoints() < 0 ? 0 : s.getPoints() + (fletch ? s.potentialPointsIfFletched() : s.inventoryPoints());
            if (materials > 0 && (projected >= goal || s.getFreeSlots() == 0 || s.getBrumaKindling() > 0))
            {
                int neededUpgrades = upgrades(s, settings, goal);
                if (fletch && s.getBrumaRoots() > 0 && neededUpgrades > 0)
                {
                    normal = ObjectiveType.FLETCH;
                    kindlingTarget = s.getBrumaKindling() + Math.min(s.getBrumaRoots(), neededUpgrades);
                }
                else { normal = ObjectiveType.FEED; }
            }
            else if (s.getFreeSlots() > 0)
            {
                normal = ObjectiveType.CHOP;
                int capacity = materials + s.getFreeSlots();
                int unitPoints = fletch ? 25 : 10;
                int need = s.getPoints() < 0 ? capacity : Math.max(1, ceil(goal - s.getPoints(), unitPoints));
                if (settings.getStrategy() == WintertodtStrategy.LOW_ATTENTION
                    || settings.getPointGoal() == PointGoal.MAXIMUM_PRACTICAL) { need = capacity; }
                int preferred = settings.getStrategy() == WintertodtStrategy.MASS_BALANCED ? 20 : capacity;
                if (s.getRoundBudgetSeconds() < 0 && s.getEndUrgency() == EndUrgency.ENDING_SOON) { preferred = Math.min(preferred, 3); }
                batchTarget = Math.min(capacity, Math.max(materials + 1, Math.min(need, preferred)));
            }
            else
            {
                return action(ObjectiveType.WAIT, "Make space for bruma roots", "inventory_blocked", TargetKind.NONE);
            }
        }
        if (normal == ObjectiveType.FLETCH)
        {
            int count = Math.min(s.getBrumaRoots(), Math.max(0, kindlingTarget - s.getBrumaKindling()));
            if (s.getRoundBudgetSeconds() >= 0)
            {
                count = Math.min(count, WintertodtFinishPlan.fletchCapacity(s));
                kindlingTarget = Math.min(kindlingTarget, s.getBrumaKindling() + count);
            }
            if (count == 0) { normal = ObjectiveType.FEED; return feed(s, "finish_feed", true); }
            return fletch(s, count, "batch_fletch", false);
        }
        if (normal == ObjectiveType.FEED) { return feed(s, "batch_feed", false); }
        if (!s.isHasAxe()) { return tool(TargetKind.AXE_CRATE, "missing_axe"); }
        int remaining = Math.max(1, batchTarget - materials);
        if (s.getRoundBudgetSeconds() >= 0)
        {
            // Limit today's instruction without permanently shrinking the resource batch.
            // A corrected forecast may leave room for more of the original batch next tick.
            remaining = Math.min(remaining, Math.max(1, additionalRoots(s, settings, goal)));
        }
        return new WintertodtObjective(ObjectiveType.CHOP, "Chop " + remaining + " bruma roots",
            "batch_chop", TargetKind.ROOTS, remaining, false);
    }

    private static int minimumBatch(WintertodtSnapshot s, PlannerSettings settings, int goal)
    {
        // XP mode values every root that fits; reward strategies can avoid tiny trips.
        if (settings.getStrategy() == WintertodtStrategy.MASS_XP) { return 1; }
        // A small trip can still be worthwhile if it secures a reward threshold.
        return s.rewardThresholdReached() ? Math.min(6, Math.max(1, ceil(goal - s.getPoints(), settings.fletch(s) ? 25 : 10))) : 1;
    }

    private static int additionalRoots(WintertodtSnapshot s, PlannerSettings settings, int goal)
    {
        boolean fletch = settings.fletch(s);
        int existingFletches = fletch ? Math.min(s.getBrumaRoots(), upgrades(s, settings, goal)) : 0;
        return WintertodtFinishPlan.additionalRoots(s, fletch, existingFletches);
    }

    private WintertodtObjective finish(WintertodtSnapshot s, PlannerSettings settings, int goal)
    {
        int materials = s.getBrumaRoots() + s.getBrumaKindling();
        if (materials == 0)
        {
            if (finishing) { finishComplete = true; }
            finishing = false;
            if (s.getRoundBudgetSeconds() >= 0 && additionalRoots(s, settings, goal) == 0)
            { return action(ObjectiveType.WAIT, "Round ending - no time for another root", "finish_wait", TargetKind.NONE); }
            if (finishComplete && ((s.getRoundBudgetSeconds() >= 0
                && additionalRoots(s, settings, goal) < minimumBatch(s, settings, goal))
                || (s.getRoundBudgetSeconds() < 0 && settings.getStrategy() != WintertodtStrategy.MASS_XP)))
            { return action(ObjectiveType.WAIT, "Final fuel fed - wait for the next round", "finish_wait", TargetKind.NONE); }
            finishComplete = false;
            return null;
        }
        boolean timed = s.getRoundBudgetSeconds() >= 0;
        boolean stopChopping = timed && additionalRoots(s, settings, goal) == 0;
        if (!finishing && !stopChopping) { return null; }
        if (!finishing)
        {
            finishing = true;
            int count = settings.fletch(s) ? Math.min(upgrades(s, settings, goal), WintertodtFinishPlan.fletchCapacity(s)) : 0;
            // Keep an existing smaller fletching target; do not restart a feeding batch.
            if (normal == ObjectiveType.FEED) { count = 0; }
            else if (normal == ObjectiveType.FLETCH) { count = Math.min(count, Math.max(0, kindlingTarget - s.getBrumaKindling())); }
            kindlingTarget = s.getBrumaKindling() + count;
            normal = count > 0 ? ObjectiveType.FLETCH : ObjectiveType.FEED;
        }
        int count = Math.min(s.getBrumaRoots(), Math.max(0, kindlingTarget - s.getBrumaKindling()));
        if (timed) { count = Math.min(count, WintertodtFinishPlan.fletchCapacity(s)); }
        else { count = 0; } // Lost forecast: preserve feeding time rather than gamble on fletching.
        kindlingTarget = Math.min(kindlingTarget, s.getBrumaKindling() + count);
        if (normal == ObjectiveType.FLETCH && count > 0) { return fletch(s, count, "finish_fletch", true); }
        normal = ObjectiveType.FEED;
        return feed(s, "finish_feed", true);
    }

    private WintertodtObjective fletch(WintertodtSnapshot s, int count, String reason, boolean urgent)
    {
        if (s.getBrazierDistance() != 0)
        {
            return new WintertodtObjective(ObjectiveType.POSITION, "Move beside the brazier to fletch",
                "fletch_at_brazier", TargetKind.BRAZIER, count, urgent);
        }
        return new WintertodtObjective(ObjectiveType.FLETCH,
            urgent ? "Fletch " + count + " roots, then feed" : s.isInterrupted() ? "Continue fletching" : "Fletch " + count + " roots",
            reason, TargetKind.NONE, count, urgent, ItemID.KNIFE, ItemID.FLETCHING_KNIFE, ItemID.WINT_BRUMA_ROOT);
    }

    private WintertodtObjective prepare(WintertodtSnapshot s, PlannerSettings settings)
    {
        TargetKind crate = TargetKind.NONE;
        if (!s.isHasAxe()) { crate = TargetKind.AXE_CRATE; }
        else if (!s.isHasHammer()) { crate = TargetKind.HAMMER_CRATE; }
        else if (!s.isHasKnife() && WintertodtGuidance.needsKnife(settings))
        { crate = TargetKind.KNIFE_CRATE; }
        else if (!s.isHasTinderbox() && !s.isHasBrumaTorch())
        { crate = TargetKind.TINDERBOX_CRATE; }
        if (crate != TargetKind.NONE)
        {
            if (s.getFreeSlots() == 0) { return makeSpace(s, "tools"); }
            return tool(crate, "prepare_tools");
        }
        // A partial reserve is enough to finish a short remaining window. Do not
        // send carried fuel on a late supply trip just to round doses up to a bottle.
        boolean shortWindow = s.getRoundBudgetSeconds() >= 0 && s.getRoundBudgetSeconds() <= 60
            || s.getEndUrgency() != EndUrgency.NORMAL;
        if (s.active() && shortWindow && (s.getRejuvenationDoses() > 0 || s.getBrumaRoots() + s.getBrumaKindling() > 0))
        {
            if (preparationDoseTarget == 0)
            { preparationDoseTarget = WintertodtSupplyPlan.recommendedPotions(s, settings.getRestoreWarmth()) * 4; }
            suppliesReady = true;
            return null;
        }
        // Do not replenish every consumed dose mid-round. Start another supply trip only
        // when empty; a round transition resets this latch in the plugin.
        if (suppliesReady && s.active() && s.getRejuvenationDoses() > 0) { return null; }
        if (preparationDoseTarget == 0 || suppliesReady)
        {
            preparationDoseTarget = WintertodtSupplyPlan.recommendedPotions(s, settings.getRestoreWarmth()) * 4;
            suppliesReady = false;
        }
        if (s.getRejuvenationDoses() >= preparationDoseTarget)
        {
            suppliesReady = true;
            return null;
        }
        int bottles = (preparationDoseTarget - s.getRejuvenationDoses() + 3) / 4;
        return potion(s, bottles, "prepare_supply");
    }

    private WintertodtObjective makeSpace(WintertodtSnapshot s, String resource)
    {
        if (s.active() && s.getLocalBrazierState() == BrazierState.LIT
            && s.getBrumaRoots() + s.getBrumaKindling() > 0)
        {
            return feed(s, "make_space_for_" + resource, false);
        }
        return action(ObjectiveType.WAIT, "Make space for " + resource, "supply_inventory_blocked", TargetKind.NONE);
    }

    private WintertodtObjective potion(WintertodtSnapshot s, int bottles, String reason)
    {
        if (s.getUnfinishedPotionCount() > 0 && s.getBrumaHerbCount() > 0)
        {
            int count = Math.min(bottles, Math.min(s.getBrumaHerbCount(), s.getUnfinishedPotionCount()));
            return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
                s.isCanMixPotion() ? "Mix " + count + " potion" + (count == 1 ? "" : "s")
                    : WintertodtGuidance.supplyInstruction(TargetKind.BREWMA, count),
                "mix_rejuvenation", s.isCanMixPotion() ? TargetKind.NONE : TargetKind.BREWMA,
                count, false,
                ItemID.WINT_HERB, ItemID.WINT_VIAL);
        }
        if (s.getFreeSlots() == 0) { return makeSpace(s, "potion ingredients"); }
        // Gather enough vials, then herbs, but leave room for at least one herb to mix.
        boolean takeVial = s.getUnfinishedPotionCount() < bottles
            && (s.getFreeSlots() > 1 || s.getUnfinishedPotionCount() == 0 || s.getBrumaHerbCount() > 0);
        int capacity = takeVial && s.getBrumaHerbCount() == 0 ? s.getFreeSlots() - 1 : s.getFreeSlots();
        if (capacity == 0) { return makeSpace(s, "potion ingredients"); }
        int remaining = Math.min(capacity, takeVial ? bottles - s.getUnfinishedPotionCount() : Math.max(1, bottles - s.getBrumaHerbCount()));
        return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
            WintertodtGuidance.supplyInstruction(takeVial ? TargetKind.POTION_CRATE : TargetKind.HERBS, remaining),
            reason, takeVial ? TargetKind.POTION_CRATE : TargetKind.HERBS,
            Math.min(remaining, s.getFreeSlots()), false);
    }

    private WintertodtObjective feed(WintertodtSnapshot s, String reason, boolean urgent)
    {
        return new WintertodtObjective(ObjectiveType.FEED,
            "finish_feed".equals(reason) ? "Continue feeding brazier"
                : urgent && !s.rewardThresholdReached() ? "Feed now - secure 500 points"
                : s.isInterrupted() ? "Continue feeding" : "Feed the brazier",
            reason, TargetKind.BRAZIER, s.getBrumaRoots() + s.getBrumaKindling(), urgent,
            s.getBrumaKindling() > 0 ? ItemID.WINT_BRUMA_KINDLING : ItemID.WINT_BRUMA_ROOT);
    }
    private WintertodtObjective action(ObjectiveType type, String text, String reason, TargetKind target)
    {
        return new WintertodtObjective(type, text, reason, target, 0, false);
    }
    private WintertodtObjective tool(TargetKind target, String reason)
    {
        return new WintertodtObjective(ObjectiveType.GET_TOOL, WintertodtGuidance.supplyInstruction(target, 1),
            reason, target, 1, false);
    }
    private static int upgrades(WintertodtSnapshot s, PlannerSettings settings, int goal)
    {
        if (s.getPoints() < 0 || settings.getFletchMode() == FletchMode.ALWAYS
            || settings.getPointGoal() == PointGoal.MAXIMUM_PRACTICAL) { return s.getBrumaRoots(); }
        return Math.max(0, ceil(goal - s.getPoints() - s.inventoryPoints(),
            WintertodtConstants.KINDLING_POINTS - WintertodtConstants.ROOT_POINTS));
    }
    private static int ceil(int n, int d) { return (Math.max(0, n) + d - 1) / d; }
}

package com.wintertodtautopilot;

/** Conservative planning costs, including walking rather than assuming run is enabled. */
public final class WintertodtFinishPlan
{
    public static final double FEED_SECONDS = 1.8;
    public static final double FLETCH_SECONDS = 1.8;
    /** A fletching knife, carried or wielded, saves one tick on every root after the first in a batch. */
    public static final double FLETCHING_KNIFE_SECONDS = 1.2;
    public static final double CHOP_SECONDS = 3.6;
    private WintertodtFinishPlan() { }

    public static double travelSeconds(WintertodtSnapshot s)
    {
        // An unknown/unloaded brazier needs a conservative allowance, not zero travel.
        return s.getBrazierDistance() < 0 ? 10 : s.getBrazierDistance() * .6 + 1.2;
    }
    public static double fletchSeconds(WintertodtSnapshot s)
    {
        return s.isHasFletchingKnife() ? FLETCHING_KNIFE_SECONDS : FLETCH_SECONDS;
    }
    /** The first root of a batch always takes the full time. */
    private static double batchStartSeconds(WintertodtSnapshot s) { return FLETCH_SECONDS - fletchSeconds(s); }
    public static int fletchCapacity(WintertodtSnapshot s)
    {
        if (s.getRoundBudgetSeconds() < 0) { return 0; }
        double spare = s.getRoundBudgetSeconds() - travelSeconds(s)
            - (s.getBrumaRoots() + s.getBrumaKindling()) * FEED_SECONDS;
        return Math.min(s.getBrumaRoots(), Math.max(0, (int) Math.floor((spare - batchStartSeconds(s)) / fletchSeconds(s))));
    }
    public static int additionalRoots(WintertodtSnapshot s, boolean fletch)
    {
        return additionalRoots(s, fletch, fletch ? s.getBrumaRoots() : 0);
    }
    public static int additionalRoots(WintertodtSnapshot s, boolean fletch, int existingFletches)
    {
        double committed = travelSeconds(s) + (s.getBrumaRoots() + s.getBrumaKindling()) * FEED_SECONDS
            + existingFletches * fletchSeconds(s) + (fletch || existingFletches > 0 ? batchStartSeconds(s) : 0);
        return Math.max(0, (int) Math.floor((s.getRoundBudgetSeconds() - committed)
            / (CHOP_SECONDS + FEED_SECONDS + (fletch ? fletchSeconds(s) : 0))));
    }
}

package com.wintertodtautopilot;

/** Shared, player-facing explanations. No client access or speculative next steps. */
public final class WintertodtGuidance
{
    private WintertodtGuidance() { }

    public static int rewardTarget(PointGoal goal, int points)
    {
        int target = goal.target(points);
        return points >= target ? PointGoal.NEXT_THRESHOLD.target(points) : target;
    }

    public static boolean needsKnife(PlannerSettings settings)
    {
        return settings.getFletchMode() == FletchMode.ALWAYS
            || settings.getFletchMode() == FletchMode.AUTOMATIC
            && settings.getStrategy() != WintertodtStrategy.MASS_XP;
    }

    public static boolean isSupplyTarget(WintertodtObjective o)
    {
        return o != null && (o.getType() == ObjectiveType.GET_TOOL
            || o.getType() == ObjectiveType.MAKE_REJUVENATION && o.getTarget() != TargetKind.NONE);
    }

    public static String supplyInstruction(TargetKind target, int quantity)
    {
        int count = Math.max(1, quantity);
        switch (target)
        {
            case AXE_CRATE: return "Take 1 axe";
            case HAMMER_CRATE: return "Take 1 hammer";
            case KNIFE_CRATE: return "Take 1 knife";
            case TINDERBOX_CRATE: return "Take 1 tinderbox";
            case POTION_CRATE: return "Take " + count + " unfinished potion" + (count == 1 ? "" : "s");
            case HERBS: return "Pick " + count + " bruma herb" + (count == 1 ? "" : "s");
            case BREWMA: return "Mix " + count + " potion" + (count == 1 ? "" : "s") + " with Brew'ma";
            default: return null;
        }
    }

    public static String phase(WintertodtSnapshot s)
    {
        switch (s.getRoundState())
        {
            case OUTSIDE: return "Ready when you are";
            case LOBBY: return "Preparation area";
            case COUNTDOWN: return s.getSecondsToStart() > 0 ? "Starts in " + s.getSecondsToStart() + "s" : "Waiting for next round";
            case COMPLETE: return "Round complete";
            case ENDING: return "Round ending";
            default: return "Round in progress";
        }
    }

    /** Acknowledges an observed action so the player does not keep clicking it. */
    public static boolean performing(WintertodtSnapshot s, WintertodtObjective o)
    {
        if (o == null) { return false; }
        switch (o.getType())
        {
            case CHOP: return s.getCurrentActivity() == PlayerActivity.CHOPPING;
            case FLETCH: return s.getCurrentActivity() == PlayerActivity.FLETCHING;
            case FEED: return s.getCurrentActivity() == PlayerActivity.FEEDING;
            case LIGHT: return s.getCurrentActivity() == PlayerActivity.LIGHTING;
            case REPAIR: return s.getCurrentActivity() == PlayerActivity.REPAIRING;
            case HEAL_PYROMANCER: return s.getCurrentActivity() == PlayerActivity.HEALING;
            case RESTORE_WARMTH: return s.getCurrentActivity() == PlayerActivity.RESTORING_WARMTH;
            case MAKE_REJUVENATION: return s.getCurrentActivity() == PlayerActivity.MAKING_POTION
                && "mix_rejuvenation".equals(o.getReason());
            default: return false;
        }
    }

    public static String status(WintertodtSnapshot s, WintertodtObjective o)
    {
        if ("inventory_blocked".equals(o.getReason()) || "supply_inventory_blocked".equals(o.getReason()))
        { return "ACTION NEEDED"; }
        if (performing(s, o)) { return "IN PROGRESS"; }
        if (WintertodtHighlight.needsRestart(s, o)) { return "RESUME"; }
        if (o.isUrgent()) { return "ACT NOW"; }
        return o.actionable() ? "NEXT ACTION" : "STAND BY";
    }

    public static String reassurance(WintertodtSnapshot s, WintertodtObjective o)
    {
        if (o.getReason().startsWith("solo_recovery"))
        { return "Leave braziers unlit. Recovery can take time; watch the energy trend."; }
        if ("solo_coverage_unknown".equals(o.getReason()) || "solo_signals_unknown".equals(o.getReason()))
        { return "Guidance needs fresh observations before recommending a relight."; }
        if ("solo_points_heal".equals(o.getReason()))
        { return "Heal the marked pyromancer. You can fletch roots while running."; }
        if ("solo_remote_lit".equals(o.getReason())) { return "A remote brazier is still lit. Avoid adding drain at home."; }
        if ("solo_rapid_drain".equals(o.getReason())) { return "Energy is dropping quickly. Feed carried fuel while checking the arena."; }
        if (performing(s, o)) { return "Keep going. Guidance updates when you need to act."; }
        if ("finish_feed".equals(o.getReason()) || "round_ending".equals(o.getReason()))
        { return "Feed your fuel before the round ends."; }
        if (o.getType() == ObjectiveType.WAIT || o.getType() == ObjectiveType.ROUND_COMPLETE)
        { return "inventory_blocked".equals(o.getReason()) || "supply_inventory_blocked".equals(o.getReason())
            ? "Free an inventory slot to continue." : "Guidance updates automatically. Watch for the next action."; }
        if (o.getType() == ObjectiveType.FLETCH) { return "Use your knife on the highlighted roots."; }
        if (o.getType() == ObjectiveType.RESTORE_WARMTH) { return "Restore warmth before continuing."; }
        if ("mix_rejuvenation".equals(o.getReason()))
        { return o.getTarget() == TargetKind.BREWMA ? "Brew'ma can mix the ingredients for you." : "Use a bruma herb on an unfinished potion."; }
        return o.getTarget() == TargetKind.NONE ? "Follow the highlighted inventory items." : "Click the highlighted target.";
    }

    public static String explanation(WintertodtObjective o)
    {
        if (o == null) { return "Visit Wintertodt on a mass world. Your next action and supply checks appear here automatically."; }
        String reason = o.getReason();
        switch (reason)
        {
            case "solo_restock": return "Replenish the Solo working reserve for warmth and pyromancer healing. Further restocks may be needed.";
            case "solo_light": return "Current energy and all four brazier observations permit lighting this corner.";
            case "solo_repair": return "Repair this destination before lighting. Energy is checked again on the next tick.";
            case "solo_points_heal": return "In Points mode, heal observed damage for points. While fletching, nearby injured pyromancers are useful healing opportunities.";
            case "solo_fletch_inside": return "Fletching is allowed at the roots and while running, but not in the safe preparation area.";
            case "solo_heal": return "Heal this corner's incapacitated pyromancer. Keep a spare dose for personal warmth.";
            case "solo_heal_reserve": return "Prepare more potions before spending your last personal warmth dose.";
            case "solo_goal_feed": return "Carried points could meet your goal. Feed them first; only earned points trigger finishing.";
            case "solo_finish_feed": return "Finishing is active. Feed carried fuel before lighting additional braziers.";
            case "solo_finish_drain": return "Maintain the selected finish pair, or one nearby brazier when run energy is low.";
            case "solo_batch_chop": return "Gather this Solo batch. The mass finish-time estimate does not control Solo gathering.";
            case "solo_batch_fletch": return "Convert the current roots to kindling before feeding them.";
            case "solo_batch_feed": return "Feed your batch to earn its points, then gather toward the fixed Solo goal.";
            case "solo_observe_corner": return "Move to this destination and acquire the scene object before maintenance guidance.";
            case "solo_observe_pyromancer": return "The destination's pyromancer must be directly observed before lighting.";
            case "warmth_low": return "Warmth has reached your restore threshold. Use the highlighted food or potion before continuing.";
            case "no_warmth_supplies": return "You have no detected usable food or potion. Reach the safe lobby before gathering more supplies.";
            case "prepare_tools": return "Take the missing tool from the highlighted crate. Equipped axes and bruma torches count too.";
            case "missing_axe": return "An axe is required to chop bruma roots. Take one from the crate or equip your own.";
            case "missing_hammer": return "A hammer is needed to repair this brazier.";
            case "missing_tinderbox": return "Use a tinderbox or bruma torch to relight the brazier.";
            case "supply_inventory_blocked": return "Free an inventory slot, then follow the highlighted supply step.";
            case "inventory_blocked": return "Your inventory is full and contains no usable bruma fuel. Free a slot to continue.";
            case "mix_rejuvenation": return o.getTarget() == TargetKind.BREWMA
                ? "Brew'ma can mix your bruma herb and unfinished potion without Druidic Ritual."
                : "Use a bruma herb on an unfinished rejuvenation potion. Each finished bottle provides four doses.";
            case "prepare_supply": return "Gather a reserve for warmth and pyromancer healing. This is a mass-round estimate; food and warm clothing reduce it.";
            case "heal_supply": return "Your local pyromancer needs a potion dose. Gather ingredients to help them.";
            case "brazier_broken": return "Repair your working brazier before feeding or relighting it.";
            case "local_pyromancer_down": return "Use a rejuvenation potion on the pyromancer so the brazier can drain Wintertodt's energy again.";
            case "brazier_unlit": return "Your pyromancer is healthy. Relight the brazier before feeding fuel.";
            case "brazier_unobserved": return "The local brazier is not currently observed. Move closer so guidance can check its state.";
            case "pyromancer_unobserved": return "Move closer to check the pyromancer before trying to relight.";
            case "ending_pyromancer_blocked": return "The brazier cannot be relit until its pyromancer is healed. Avoid a long supply trip this late in the round.";
            case "fletch_at_brazier": return "Move to the highlighted tile beside your working brazier, then use the knife on your roots. Stay close for repairs, relighting and feeding.";
            case "finish_fletch": return "The observed round pace leaves time for this smaller fletching batch after reserving walking and feeding time. Feed as soon as it is ready.";
            case "finish_feed": return "The remaining time is needed for walking and feeding. Stop chopping or fletching and use your carried fuel now.";
            case "finish_wait": return "The time budget is too short to chop another root and feed it. Wait for the next round.";
            case "batch_chop": return "Gather the remaining roots for this batch. Low warmth and the end of the round can interrupt it.";
            case "batch_fletch": return "Use your knife on bruma roots. Kindling earns 25 points per feed; a root earns 10.";
            case "batch_feed": return "Feed your carried fuel to secure its points. Inventory projections only count once the fuel is fed.";
            case "ending_secure_500": return "The round is ending. Feed existing fuel now to work toward the 500-point reward minimum.";
            case "round_ending": return "Feed existing fuel before the round ends; there may not be time to finish fletching.";
            case "ending_secured": return "You have at least 500 points and no fuel remaining. Wait for the round to finish.";
            case "ending_no_fuel": return "The round is almost over and you have no fuel remaining.";
            case "countdown_position": return "Stand near your working brazier so you are ready when the round starts.";
            case "round_complete": return "The round has finished. Check your supplies before the next countdown.";
            case "lobby": return "Enter the prison to join a round. Supply preparation follows once you are inside.";
            case "countdown": return "Your supplies are prepared. Wait for the next round.";
            default: return reason.startsWith("make_space_for_")
                ? "Feed carried fuel to make room for the missing supplies."
                : "Follow the highlighted target or inventory items. You perform every interaction.";
        }
    }
}

package com.wintertodtautopilot;

import java.awt.*;
import net.runelite.api.gameval.ItemID;

/** Shared scene/inventory animation, with no mutation of planner state. */
final class WintertodtHighlight
{
    private WintertodtHighlight() { }
    static boolean needsRestart(WintertodtSnapshot snapshot, WintertodtObjective objective)
    {
        return snapshot.active() && snapshot.isInterrupted() && objective != null && objective.actionable()
            && snapshot.getCurrentActivity() == PlayerActivity.IDLE;
    }
    static boolean needsAttention(WintertodtSnapshot s, WintertodtObjective o)
    {
        boolean blocked = o != null && ("inventory_blocked".equals(o.getReason()) || "supply_inventory_blocked".equals(o.getReason()));
        if (o == null || (!s.active() && o.getType() != ObjectiveType.RESTORE_WARMTH)
            || (!o.actionable() && !blocked)
            || (s.getCurrentActivity() == PlayerActivity.MOVING && o.getType() != ObjectiveType.RESTORE_WARMTH))
        { return false; }
        if (WintertodtGuidance.performing(s, o)) { return false; }
        return blocked || needsRestart(s, o) || s.isPlayerIdle() || o.isUrgent()
            || o.getType() == ObjectiveType.RESTORE_WARMTH || o.getType() == ObjectiveType.REPAIR
            || o.getType() == ObjectiveType.LIGHT || o.getType() == ObjectiveType.HEAL_PYROMANCER
            || o.getType() == ObjectiveType.FEED && (s.getCurrentActivity() == PlayerActivity.FLETCHING || s.getCurrentActivity() == PlayerActivity.CHOPPING)
            || o.getType() == ObjectiveType.FLETCH && s.getCurrentActivity() == PlayerActivity.CHOPPING;
    }
    static boolean inventoryItem(WintertodtSnapshot s, WintertodtObjective o, int itemId)
    {
        if (o == null || s.getRoundState() == RoundState.OUTSIDE || WintertodtGuidance.performing(s, o)) { return false; }
        // Healing uses a finished potion, never fuel carried for a later feeding step.
        if (o.getType() == ObjectiveType.HEAL_PYROMANCER && WintertodtConstants.doses(itemId) == 0) { return false; }
        return o.getItemIds().contains(itemId);
    }

    static Color inventoryColor(WintertodtObjective objective, int itemId)
    {
        // Keep the tool amber and give its fletching target a softer gold tone.
        return objective.getType() == ObjectiveType.FLETCH && itemId == ItemID.WINT_BRUMA_ROOT
            ? new Color(255, 215, 130) : WintertodtOverlay.color(objective);
    }

    static float strength(WintertodtSnapshot snapshot, WintertodtObjective objective, boolean enabled)
    {
        return strengthAt(snapshot, objective, enabled, System.nanoTime());
    }
    static float strengthAt(WintertodtSnapshot snapshot, WintertodtObjective objective, boolean enabled, long nanos)
    {
        return enabled && needsAttention(snapshot, objective)
            ? (float) (.625 + .375 * Math.sin(nanos / 1_000_000_000.0 * Math.PI * 2 / 1.2)) : 1;
    }
    static Color alpha(Color color, int alpha)
    {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
    }
    static void tile(Graphics2D graphics, Polygon tile, Color color, float strength, boolean destination)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(alpha(color, (int) ((destination ? 28 : 10) * strength))); g.fillPolygon(tile);
            g.setStroke(new BasicStroke(destination ? 4 : 2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(new Color(0, 0, 0, 160)); g.drawPolygon(tile);
            softEdge(g, tile, color, destination ? 1.5f + strength : 1, strength);
            g.setStroke(new BasicStroke(destination ? 1.5f + strength : 1));
            g.setColor(alpha(color, (int) (240 * strength))); g.drawPolygon(tile);
        }
        finally { g.dispose(); }
    }
    static void routeEdge(Graphics2D graphics, net.runelite.api.Point a, net.runelite.api.Point b, Color color, float strength)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setStroke(new BasicStroke(4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(new Color(0, 0, 0, 165)); g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
            softEdge(g, new java.awt.geom.Line2D.Float(a.getX(), a.getY(), b.getX(), b.getY()), color, 1.6f, strength);
            g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(alpha(color, (int) (235 * strength))); g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
            g.setStroke(new BasicStroke(.5f)); g.setColor(new Color(255, 255, 255, (int) (130 * strength)));
            g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
        }
        finally { g.dispose(); }
    }
    static void inventory(Graphics2D graphics, Rectangle bounds, Color color, float strength)
    {
        inventory(graphics, bounds, color, strength, 1);
    }
    static void inventory(Graphics2D graphics, Rectangle bounds, Color color, float strength, int borderWidth)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(alpha(color, (int) (30 * strength))); g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 7, 7);
            float width = Math.max(1, Math.min(4, borderWidth));
            g.setStroke(new BasicStroke(width + 1)); g.setColor(new Color(0, 0, 0, (int) (100 * strength)));
            g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 7, 7);
            g.setStroke(new BasicStroke(width)); g.setColor(alpha(color, (int) (250 * strength)));
            g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 7, 7);
        }
        finally { g.dispose(); }
    }
    private static void softEdge(Graphics2D g, Shape shape, Color color, float width, float strength)
    {
        g.setStroke(new BasicStroke(width + 3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(alpha(color, (int) (18 * strength))); g.draw(shape);
        g.setStroke(new BasicStroke(width + 1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(alpha(color, (int) (42 * strength))); g.draw(shape);
    }

}

package com.wintertodtautopilot;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.HintArrowType;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

/** Only claim a free arrow; only clear the arrow we still own. */
@Singleton
public class WintertodtHintArrow
{
    @Inject private Client client;
    private NPC npc;
    private WorldPoint point;
    private boolean owns()
    {
        return npc != null && client.getHintArrowType() == HintArrowType.NPC && client.getHintArrowNpc() == npc
            || point != null && client.getHintArrowType() == HintArrowType.COORDINATE && point.equals(client.getHintArrowPoint());
    }
    public void clear()
    {
        if (owns()) { client.clearHintArrow(); }
        npc = null; point = null;
    }
    public void update(NPC nextNpc, WorldPoint nextPoint, boolean enabled)
    {
        if (nextNpc != null) { nextPoint = null; }
        if (!enabled || nextNpc == null && nextPoint == null) { clear(); return; }
        if (!owns() && client.getHintArrowType() != HintArrowType.NONE)
        {
            npc = null; point = null; return;
        }
        if (nextNpc == npc && java.util.Objects.equals(point, nextPoint) && owns()) { return; }
        clear();
        if (nextNpc != null) { npc = nextNpc; client.setHintArrow(npc); }
        else { point = nextPoint; client.setHintArrow(point); }
    }
}

package com.wintertodtautopilot;

import java.awt.*;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/** Larger wrapped instruction; its reported height keeps supporting rows below it. */
final class WintertodtInstructionComponent implements LayoutableRenderableEntity
{
    private final String text;
    private final Color color;
    private final Font font;
    @Setter private Point preferredLocation = new Point();
    @Setter private Dimension preferredSize = new Dimension(260, 0);
    @Getter private final Rectangle bounds = new Rectangle();
    WintertodtInstructionComponent(String text, Color color)
    { this(text, color, new Font(Font.SANS_SERIF, Font.BOLD, 14)); }
    WintertodtInstructionComponent(String text, Color color, Font font)
    { this.text = text; this.color = color; this.font = font; }
    @Override
    public Dimension render(Graphics2D graphics)
    {
        Font old = graphics.getFont();
        graphics.setFont(font);
        try
        {
            FontMetrics metrics = graphics.getFontMetrics();
            int y = preferredLocation.y;
            String line = "";
            for (String word : text.split(" "))
            {
                String next = line.isEmpty() ? word : line + " " + word;
                if (!line.isEmpty() && metrics.stringWidth(next) > preferredSize.width)
                {
                    y += metrics.getHeight(); draw(graphics, line, y); line = word;
                }
                else { line = next; }
            }
            y += metrics.getHeight(); draw(graphics, line, y);
            Dimension size = new Dimension(preferredSize.width, y - preferredLocation.y + 3);
            bounds.setLocation(preferredLocation); bounds.setSize(size);
            return size;
        }
        finally { graphics.setFont(old); }
    }
    private void draw(Graphics2D graphics, String line, int y)
    {
        TextComponent component = new TextComponent();
        component.setText(line); component.setColor(color);
        component.setPosition(new Point(preferredLocation.x, y)); component.render(graphics);
    }
}

