import lombok.Value;

@Value
public class WintertodtObjective
{
    ObjectiveType type;
    String instruction;
    String reason;
    TargetKind target;
    Set<Integer> itemIds;
    int quantity;
    boolean urgent;
    /** AUTOMATIC keeps the mass planner's working-corner behavior. */
    WorkingCorner destination;
    public WintertodtObjective(ObjectiveType type, String instruction, String reason,
        TargetKind target, int quantity, boolean urgent, int... items)
    {
        this(type, instruction, reason, target, WorkingCorner.AUTOMATIC, quantity, urgent, items);
    }
    public WintertodtObjective(ObjectiveType type, String instruction, String reason,
        TargetKind target, WorkingCorner destination, int quantity, boolean urgent, int... items)
    {
        this.destination = destination;
        this.type = type; this.instruction = instruction; this.reason = reason;
        this.target = target; this.quantity = quantity; this.urgent = urgent;
        Set<Integer> ids = new HashSet<>();
        for (int id : items) { if (id >= 0) { ids.add(id); } }
        itemIds = Collections.unmodifiableSet(ids);
    }
    public boolean actionable()
    {
        return type != ObjectiveType.WAIT && type != ObjectiveType.ROUND_COMPLETE;
    }
}

package com.wintertodtautopilot;

/** Stable key/value trace for live observation runs; only formatted when debug is enabled. */
final class WintertodtObservationTrace
{
    private WintertodtObservationTrace() { }

    static String format(WintertodtSnapshot s, WintertodtObjective objective)
    {
        return format(s, objective, WintertodtMode.MASS, null, "UNKNOWN", "none", false);
    }
    static String format(WintertodtSnapshot s, WintertodtObjective objective, WintertodtMode mode,
        SoloPhase phase, String trend, String transitionReason, boolean finishRequested)
    {
        StringBuilder trace = new StringBuilder("solo_observation_v1");
        trace.append(" tick=").append(s.getObservationTick())
            .append(" planner=").append(mode.name()).append(" soloPhase=").append(phase == null ? "NOT_RUNNING" : phase.name())
            .append(" round=").append(s.getRoundState())
            .append(" trend=").append(trend).append(" transitionReason=").append(transitionReason)
            .append(" finishRequested=").append(finishRequested)
            .append(" energy=").append(s.getWintertodtEnergy())
            .append(" warmth=").append(s.getWarmth()).append(" rawWarmth=").append(s.getRawWarmth())
            .append(" home=").append(s.getWorkingCorner().name())
            .append(" destination=").append(destination(s, objective))
            .append(" action=").append(objective.getType()).append(" reason=").append(objective.getReason())
            .append(" activity=").append(s.getCurrentActivity())
            .append(" doses=").append(s.getRejuvenationDoses())
            .append(" unfinished=").append(s.getUnfinishedPotionCount()).append(" herbs=").append(s.getBrumaHerbCount())
            .append(" freeSlots=").append(s.getFreeSlots()).append(" runEnergy=").append(s.getRunEnergyPercent())
            .append(" earned=").append(s.getPoints()).append(" carried=").append(s.inventoryPoints())
            .append(" roots=").append(s.getBrumaRoots()).append(" kindling=").append(s.getBrumaKindling())
            .append(" loadedLit=").append(s.getLitBraziers())
            .append(" observedGlobalLit=").append(s.observedGlobalLitBraziers());
        for (CornerObservation c : s.getCorners())
        {
            String prefix = " " + c.getCorner().name() + ".";
            trace.append(prefix).append("brazier=").append(c.getBrazierState())
                .append(prefix).append("brazierSource=").append(c.getBrazierSource())
                .append(prefix).append("brazierVisible=").append(c.isBrazierVisible())
                .append(prefix).append("brazierTick=").append(c.getBrazierObservedTick())
                .append(prefix).append("brazierFresh=").append(c.brazierFresh(s.getObservationTick()))
                .append(prefix).append("pyromancer=").append(c.getPyromancerState())
                .append(prefix).append("healthPercent=").append(c.getPyromancerHealthPercent())
                .append(prefix).append("pyromancerSource=").append(c.getPyromancerSource())
                .append(prefix).append("pyromancerVisible=").append(c.isPyromancerVisible())
                .append(prefix).append("pyromancerTick=").append(c.getPyromancerObservedTick())
                .append(prefix).append("pyromancerFresh=").append(c.pyromancerFresh(s.getObservationTick()));
        }
        return trace.toString();
    }

    private static String destination(WintertodtSnapshot s, WintertodtObjective objective)
    {
        switch (objective.getTarget())
        {
            case BRAZIER:
            case PYROMANCER:
            case ROOTS: return (objective.getDestination() == WorkingCorner.AUTOMATIC
                ? s.getWorkingCorner() : objective.getDestination()).name();
            default: return "NONE";
        }
    }
}

package com.wintertodtautopilot;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Font;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.LineComponent;

public class WintertodtOverlay extends OverlayPanel
{
    private static final Color FLAME = new Color(255, 180, 40);
    private static final Color SUPPLY_FLAME = new Color(255, 210, 75);
    private final WintertodtAutopilotPlugin plugin;
    private final WintertodtAutopilotConfig config;
    @Inject
    WintertodtOverlay(WintertodtAutopilotPlugin plugin, WintertodtAutopilotConfig config)
    {
        super(plugin); this.plugin = plugin; this.config = config;
        setPosition(OverlayPosition.BOTTOM_LEFT);
        panelComponent.setBackgroundColor(new Color(24, 29, 33, 235));
        panelComponent.setPreferredSize(new Dimension(260, 0));
        addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, "Wintertodt Autopilot");
    }
    @Override
    public Dimension render(Graphics2D graphics)
    {
        WintertodtSnapshot s = plugin.getSnapshot();
        WintertodtObjective o = plugin.getObjective();
        if (!config.showOverlay() || s.getRoundState() == RoundState.OUTSIDE || o == null) { return null; }
        if (plugin.isPaused())
        {
            panelComponent.getChildren().add(new WintertodtInstructionComponent("Guidance paused", Color.LIGHT_GRAY));
            body("Uncheck Pause guidance in plugin settings.");
            body("All guidance and notifications are paused.");
            return super.render(graphics);
        }
        Color color = color(o);
        Color textColor = o.getType() == ObjectiveType.RESTORE_WARMTH && o.isUrgent()
            ? new Color(255, 145, 130) : color;
        panelComponent.getChildren().add(LineComponent.builder()
            .left(WintertodtGuidance.status(s, o)).leftColor(o.isUrgent() ? textColor : FLAME)
            .leftFont(new Font(Font.SANS_SERIF, Font.BOLD, 11)).build());
        panelComponent.getChildren().add(new WintertodtInstructionComponent(o.getInstruction(), o.isUrgent() ? textColor : Color.WHITE));
        if (config.overlayDetail() != OverlayDetail.MINIMAL)
        {
            body(WintertodtGuidance.reassurance(s, o));
        }
        line("Warmth", percent(s.getWarmth()), s.getWarmth() >= 0 && s.getWarmth() <= config.warmthWarning() ? Color.ORANGE : Color.WHITE);
        boolean soloMode = config.mode() == WintertodtMode.SOLO;
        int target = soloMode ? Math.max(500, Math.min(100000, config.soloPointGoal()))
            : WintertodtGuidance.rewardTarget(config.pointGoal(), s.getPoints());
        if (soloMode)
        {
            line("Solo phase", plugin.getSoloPhase().toString(), new Color(130, 200, 150));
            if (plugin.isSoloFinishRequested()) { body("Finish this round requested"); }
            line("Energy / trend", percent(s.getWintertodtEnergy()) + " / " + plugin.getSoloEnergyTrend(), Color.LIGHT_GRAY);
        }
        if (s.rewardThresholdReached())
        {
            line("Reward secured", "500 points", new Color(130, 200, 150));
        }
        line(soloMode ? "Solo goal" : s.rewardThresholdReached() ? "Next target" : "Reward progress",
            number(s.getPoints()) + " / " + target, Color.WHITE);
        if (config.overlayDetail() != OverlayDetail.MINIMAL)
        {
            if (s.inventoryPoints() > 0) { line("Fuel to feed", "+" + s.inventoryPoints() + " pts", Color.LIGHT_GRAY); }
            if (s.active() && !soloMode)
            {
                line("Round ends in", s.getEstimatedSecondsLeft() < 0 ? "Learning pace" : "~" + s.getEstimatedSecondsLeft() + "s", Color.LIGHT_GRAY);
            }
            else if (!s.active()) { body(WintertodtGuidance.phase(s)); }
        }
        if (config.overlayDetail() == OverlayDetail.DETAILED || config.debug())
        {
            body(WintertodtGuidance.explanation(o));
            line("Potion doses / reserve", s.getRejuvenationDoses() + " / " + plugin.getPotionTargetDoses(), Color.WHITE);
            line("Roots / kindling", s.getBrumaRoots() + " / " + s.getBrumaKindling(), Color.WHITE);
            if (!soloMode) { line("Usable time budget", s.getRoundBudgetSeconds() < 0 ? "Unknown" : s.getRoundBudgetSeconds() + "s", Color.LIGHT_GRAY); }
            line("Wintertodt", percent(s.getWintertodtEnergy()) + (soloMode ? "" : " / " + s.getEndUrgency()), Color.WHITE);
            line("Projected total", number(s.projectedPoints()), Color.WHITE);
            line("Potential if fletched", s.getPoints() < 0 ? "Unknown" : Integer.toString(s.getPoints() + s.potentialPointsIfFletched()), Color.WHITE);
            line("Need for goal", s.getPoints() < 0 ? "Unknown" : Integer.toString(Math.max(0, target - s.getPoints())), Color.WHITE);
            line("Brazier", s.getLocalBrazierState().toString(), Color.WHITE);
            line("Pyromancer", !s.isLocalPyromancerKnown() ? "Unknown" : s.isLocalPyromancerIncapacitated() ? "Incapacitated" : "Healthy", Color.WHITE);
            line("Activity", s.getCurrentActivity().toString(), Color.WHITE);
            line("Firemaking / warm items", s.getFiremakingLevel() + " / " + (s.getWarmClothingCount() < 0 ? "Unknown" : s.getWarmClothingCount()), Color.WHITE);
            if (soloMode) { line("Run energy", percent(s.getRunEnergyPercent()), Color.WHITE); }
            line("Corner", s.getWorkingCorner().toString(), Color.WHITE);
        }
        if (config.debug())
        {
            line("Raw warmth / restore at", s.getRawWarmth() + " / " + config.restoreWarmth() + "%", Color.GRAY);
            line("Round", s.getRoundState().toString(), Color.GRAY);
            line("Objective", o.getType().toString(), Color.GRAY);
            line("Reason", o.getReason(), Color.GRAY);
            line("Interaction", s.getInteraction(), Color.GRAY);
            line("Food / doses", s.getFoodCount() + " / " + s.getRejuvenationDoses(), Color.GRAY);
            line("Idle ticks", Integer.toString(s.getInactiveTicks()), Color.GRAY);
        }
        Dimension size = super.render(graphics);
        if (size != null && config.pulseInterruptions() && WintertodtHighlight.needsAttention(s, o))
        {
            Graphics2D g = (Graphics2D) graphics.create();
            try
            {
                float strength = WintertodtHighlight.strength(s, o, true);
                g.setColor(WintertodtHighlight.alpha(color, (int) (255 * strength)));
                g.setStroke(new java.awt.BasicStroke(1 + 2 * strength));
                g.drawRoundRect(1, 1, Math.max(0, size.width - 3), Math.max(0, size.height - 3), 6, 6);
            }
            finally { g.dispose(); }
        }
        return size;
    }
    static Color color(WintertodtObjective o)
    {
        if (o.getType() == ObjectiveType.RESTORE_WARMTH) { return o.isUrgent() ? Color.RED : Color.ORANGE; }
        if (o.isUrgent()) { return Color.ORANGE; }
        if (WintertodtGuidance.isSupplyTarget(o)) { return SUPPLY_FLAME; }
        if (!o.actionable()) { return new Color(130, 200, 150); }
        return FLAME;
    }
    private static String number(int n) { return n < 0 ? "Unknown" : Integer.toString(n); }
    private static String percent(int n) { return n < 0 ? "Unknown" : n + "%"; }
    private void body(String text)
    {
        panelComponent.getChildren().add(new WintertodtInstructionComponent(text, Color.LIGHT_GRAY,
            new Font(Font.SANS_SERIF, Font.PLAIN, 12)));
    }
    private void line(String left, String right, Color color)
    {
        panelComponent.getChildren().add(LineComponent.builder().left(left + ":").leftColor(Color.LIGHT_GRAY)
            .leftFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12)).rightFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12)).right(right).rightColor(color).build());
    }
}

package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/** Calculates on game ticks, never during rendering; invalidated by scene events. */
@Singleton
public class WintertodtPathTracker
{
    @Inject private Client client;
    @Inject private WintertodtAutopilotConfig config;
    private boolean lastShortcut;
    // Three manual jumps across the northern pillars, in either direction.
    private static final int[] GAP_X = {1627, 1629, 1631, 1633};
    private static final int GAP_Y = 4023;
    @Getter private List<WorldPoint> path = Collections.emptyList();
    private WorldPoint lastPlayer, lastTarget;
    private TileObject lastObject;
    private NPC lastNpc;
    private int lastTick = -100;
    private boolean dirty = true;
    public void invalidate() { dirty = true; }
    public void reset()
    {
        path = Collections.emptyList(); lastPlayer = null; lastTarget = null;
        lastObject = null; lastNpc = null; lastTick = -100; dirty = true;
    }
    public void update(WorldPoint target, TileObject object, NPC npc, boolean enabled)
    {
        Player player = client.getLocalPlayer(); WorldView view = client.getTopLevelWorldView();
        if (!enabled || target == null || player == null || view == null || target.getPlane() != view.getPlane())
        { reset(); return; }
        WorldPoint location = player.getWorldLocation(); int tick = client.getTickCount();
        boolean shortcut = config.mode() == WintertodtMode.SOLO && view.getPlane() == 0
            && client.getRealSkillLevel(Skill.AGILITY) >= 60 && client.getBoostedSkillLevel(Skill.AGILITY) >= 60;
        if (!dirty && location.equals(lastPlayer) && target.equals(lastTarget)
            && shortcut == lastShortcut && object == lastObject && npc == lastNpc && tick - lastTick < 5) { return; }
        path = Collections.emptyList();
        lastShortcut = shortcut;
        dirty = false; lastPlayer = location; lastTarget = target; lastObject = object; lastNpc = npc; lastTick = tick;
        CollisionData[] maps = view.getCollisionMaps();
        if (maps == null || view.getPlane() >= maps.length || maps[view.getPlane()] == null) { return; }
        LocalPoint local = LocalPoint.fromWorld(view, target);
        LocalPoint start = player.getLocalLocation();
        if (local == null || start == null) { return; }
        int minX = local.getSceneX(), minY = local.getSceneY(), maxX = minX, maxY = minY;
        boolean adjacent = object != null || npc != null;
        if (object instanceof GameObject)
        {
            GameObject gameObject = (GameObject) object;
            Point min = gameObject.getSceneMinLocation(), max = gameObject.getSceneMaxLocation();
            if (min == null || max == null) { return; }
            minX = min.getX(); minY = min.getY(); maxX = max.getX(); maxY = max.getY();
        }
        else if (npc != null && npc.getTransformedComposition() != null)
        {
            int size = Math.max(1, npc.getTransformedComposition().getSize());
            maxX += size - 1; maxY += size - 1;
        }
        List<Point> jumps = new ArrayList<>();
        if (shortcut)
        {
            for (int x : GAP_X)
            {
                LocalPoint pillar = LocalPoint.fromWorld(view, new WorldPoint(x, GAP_Y, 0));
                if (pillar == null) { jumps.clear(); break; }
                jumps.add(new Point(pillar.getSceneX(), pillar.getSceneY()));
            }
        }
        List<Point> tiles = WintertodtPathfinder.find(maps[view.getPlane()].getFlags(),
            new Point(start.getSceneX(), start.getSceneY()), minX, minY, maxX, maxY, adjacent, jumps);
        List<WorldPoint> route = new ArrayList<>();
        for (Point tile : tiles) { route.add(WorldPoint.fromScene(view, tile.getX(), tile.getY(), view.getPlane())); }
        path = Collections.unmodifiableList(route);
    }
}

package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Point;

/** Bounded scene search. Walking uses collision-checked eight-way steps; only explicit shortcut edges cross gaps. */
public final class WintertodtPathfinder
{
    private static final int UNLOADED = 0x1000000;
    private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL | UNLOADED;
    private static final int[] DX = {1, 0, -1, 0, 1, -1, -1, 1};
    private static final int[] DY = {0, 1, 0, -1, 1, 1, -1, -1};
    private static final int HEADINGS = 9;
    private static final int NO_HEADING = 8;
    private WintertodtPathfinder() { }
    public static List<Point> find(int[][] flags, Point start, int minX, int minY, int maxX, int maxY, boolean adjacent)
    {
        return find(flags, start, minX, minY, maxX, maxY, adjacent, Collections.emptyList());
    }
    public static List<Point> find(int[][] flags, Point start, int minX, int minY, int maxX, int maxY,
        boolean adjacent, List<Point> shortcut)
    {
        if (flags == null || flags.length == 0 || flags[0] == null) { return Collections.emptyList(); }
        int width = flags.length, height = flags[0].length;
        if (height == 0 || !inside(start.getX(), start.getY(), width, height)) { return Collections.emptyList(); }
        for (int[] row : flags) { if (row == null || row.length != height) { return Collections.emptyList(); } }
        if (minX < 0 || minY < 0 || maxX >= width || maxY >= height) { return Collections.emptyList(); }
        // Keep arrival headings separate so ties can prefer fewer turns without losing shorter routes.
        int[] parents = new int[width * height * HEADINGS]; Arrays.fill(parents, -1);
        int origin = (start.getX() * height + start.getY()) * HEADINGS + NO_HEADING;
        parents[origin] = origin;
        int[] costs = new int[parents.length]; Arrays.fill(costs, Integer.MAX_VALUE); costs[origin] = 0;
        int[] turns = new int[parents.length]; Arrays.fill(turns, Integer.MAX_VALUE); turns[origin] = 0;
        PriorityQueue<int[]> queue = new PriorityQueue<>(Comparator.<int[]>comparingInt(entry -> entry[1])
            .thenComparingInt(entry -> entry[2]).thenComparingInt(entry -> entry[0]));
        queue.add(new int[]{origin, 0, 0});
        while (!queue.isEmpty())
        {
            int[] entry = queue.remove();
            int current = entry[0], tile = current / HEADINGS, x = tile / height, y = tile % height;
            if (entry[1] != costs[current] || entry[2] != turns[current]) { continue; }
            if (goal(x, y, minX, minY, maxX, maxY, adjacent))
            {
                List<Point> path = new ArrayList<>();
                for (int node = current; node != origin; node = parents[node])
                {
                    path.add(new Point(node / HEADINGS / height, node / HEADINGS % height));
                }
                path.add(start); Collections.reverse(path);
                return Collections.unmodifiableList(path);
            }
            for (int direction = 0; direction < DX.length; direction++)
            {
                int nx = x + DX[direction], ny = y + DY[direction];
                if (!canStep(flags, x, y, nx, ny)) { continue; }
                int next = (nx * height + ny) * HEADINGS + direction;
                int turn = current % HEADINGS == NO_HEADING || current % HEADINGS == direction ? 0 : 1;
                relax(queue, parents, costs, turns, current, next, 1, turn);
            }
            for (int i = 0; i < shortcut.size(); i++)
            {
                Point from = shortcut.get(i);
                if (from.getX() != x || from.getY() != y) { continue; }
                for (int j : new int[]{i - 1, i + 1})
                {
                    if (j < 0 || j >= shortcut.size()) { continue; }
                    Point to = shortcut.get(j);
                    int nx = to.getX(), ny = to.getY();
                    // A jump takes roughly two ticks: prefer walking when it is already shorter.
                    // Pillars may block normal walking. Only the two banks need walkable tiles;
                    // intermediate pillars are reached and left exclusively through these jumps.
                    if (!inside(nx, ny, width, height) || (flags[nx][ny] & UNLOADED) != 0
                        || (flags[x][y] & UNLOADED) != 0
                        || (j == 0 || j == shortcut.size() - 1) && (flags[nx][ny] & BLOCKED) != 0
                        || (i == 0 || i == shortcut.size() - 1) && (flags[x][y] & BLOCKED) != 0) { continue; }
                    int next = (nx * height + ny) * HEADINGS + NO_HEADING;
                    relax(queue, parents, costs, turns, current, next, 4, 0);
                }
            }
        }
        // Never fall back to a line through an unreachable obstacle.
        return Collections.emptyList();
    }
    private static void relax(PriorityQueue<int[]> queue, int[] parents, int[] costs, int[] turns,
        int current, int next, int cost, int turn)
    {
        int nextCost = costs[current] + cost, nextTurns = turns[current] + turn;
        if (nextCost > costs[next] || nextCost == costs[next] && nextTurns >= turns[next]) { return; }
        parents[next] = current; costs[next] = nextCost; turns[next] = nextTurns;
        queue.add(new int[]{next, nextCost, nextTurns});
    }
    private static boolean goal(int x, int y, int minX, int minY, int maxX, int maxY, boolean adjacent)
    {
        if (!adjacent) { return x >= minX && x <= maxX && y >= minY && y <= maxY; }
        return (x == minX - 1 || x == maxX + 1) && y >= minY && y <= maxY
            || (y == minY - 1 || y == maxY + 1) && x >= minX && x <= maxX;
    }
    static boolean canStep(int[][] flags, int x, int y, int nx, int ny)
    {
        if (!inside(x, y, flags.length, flags[0].length) || !inside(nx, ny, flags.length, flags[0].length)
            || (flags[x][y] & BLOCKED) != 0 || (flags[nx][ny] & BLOCKED) != 0) { return false; }
        int dx = nx - x, dy = ny - y;
        if (Math.abs(dx) > 1 || Math.abs(dy) > 1 || dx == 0 && dy == 0) { return false; }
        if (dx != 0 && dy != 0)
        {
            int sourceCorner, destinationCorner;
            if (dx > 0 && dy > 0)
            { sourceCorner = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST; destinationCorner = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST; }
            else if (dx > 0)
            { sourceCorner = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST; destinationCorner = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST; }
            else if (dy > 0)
            { sourceCorner = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST; destinationCorner = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST; }
            else
            { sourceCorner = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST; destinationCorner = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST; }
            // Both side tiles and all four bordering edges must be clear: never cut an obstacle corner.
            return (flags[x][y] & sourceCorner) == 0 && (flags[nx][ny] & destinationCorner) == 0
                && canStep(flags, x, y, nx, y) && canStep(flags, x, y, x, ny)
                && canStep(flags, nx, y, nx, ny) && canStep(flags, x, ny, nx, ny);
        }
        int sourceWall, destinationWall;
        if (nx > x) { sourceWall = CollisionDataFlag.BLOCK_MOVEMENT_EAST; destinationWall = CollisionDataFlag.BLOCK_MOVEMENT_WEST; }
        else if (nx < x) { sourceWall = CollisionDataFlag.BLOCK_MOVEMENT_WEST; destinationWall = CollisionDataFlag.BLOCK_MOVEMENT_EAST; }
        else if (ny > y) { sourceWall = CollisionDataFlag.BLOCK_MOVEMENT_NORTH; destinationWall = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH; }
        else { sourceWall = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH; destinationWall = CollisionDataFlag.BLOCK_MOVEMENT_NORTH; }
        return (flags[x][y] & sourceWall) == 0 && (flags[nx][ny] & destinationWall) == 0;
    }
    private static boolean inside(int x, int y, int width, int height)
    {
        return x >= 0 && y >= 0 && x < width && y < height;
    }
}

package com.wintertodtautopilot;

interface WintertodtPlanner
{
    WintertodtObjective decide(WintertodtSnapshot snapshot, PlannerSettings settings);
    int getPreparationDoseTarget();
    void reset();
}

package com.wintertodtautopilot;

import java.util.ArrayDeque;
import java.util.Deque;

/** Recent energy drain, with blended windows to avoid chasing individual HUD drops. */
public final class WintertodtRoundForecast
{
    private final Deque<int[]> samples = new ArrayDeque<>();
    private double smoothedRate;
    private int lastDropTick = -1;
    private int secondsLeft = -1;

    public int getSecondsLeft() { return secondsLeft; }
    public int getBudgetSeconds() { return secondsLeft < 0 ? -1 : Math.max(0, (int) (secondsLeft * .9) - 3); }
    public void reset()
    {
        samples.clear(); smoothedRate = 0; lastDropTick = -1; secondsLeft = -1;
    }
    public void observe(int energy, int tick, int lit)
    {
        if (energy <= 0 || energy > 100 || lit <= 0) { reset(); return; }
        if (!samples.isEmpty() && (energy > samples.getLast()[1] || tick <= samples.getLast()[0]))
        { reset(); }
        boolean dropped = !samples.isEmpty() && energy < samples.getLast()[1];
        if (samples.isEmpty() || dropped) { lastDropTick = tick; }
        samples.addLast(new int[]{tick, energy});
        while (!samples.isEmpty() && tick - samples.getFirst()[0] > 150) { samples.removeFirst(); }
        secondsLeft = -1;
        // A stopped drain must not leave a convincing but stale countdown.
        if (tick - lastDropTick > 20) { return; }
        double longRate = rate(tick, 150), recentRate = rate(tick, 60);
        if (longRate <= 0) { return; }
        double rate = recentRate > 0 ? longRate * .65 + recentRate * .35 : longRate;
        if (smoothedRate == 0) { smoothedRate = rate; }
        else if (dropped) { smoothedRate = smoothedRate * .6 + rate * .4; }
        secondsLeft = (int) Math.ceil(energy * .6 / smoothedRate);
    }
    private double rate(int tick, int window)
    {
        int count = 0, changes = 0, firstTick = -1, firstEnergy = -1, lastEnergy = -1;
        double sumT = 0, sumE = 0, sumTT = 0, sumTE = 0;
        for (int[] sample : samples)
        {
            if (tick - sample[0] > window) { continue; }
            if (firstTick < 0) { firstTick = sample[0]; firstEnergy = sample[1]; }
            double t = sample[0] - tick;
            double e = sample[1];
            ++count; sumT += t; sumE += e; sumTT += t * t; sumTE += t * e;
            if (lastEnergy >= 0 && sample[1] < lastEnergy) { ++changes; }
            lastEnergy = sample[1];
        }
        // Thirty ticks and three separate drops prevent a single burst becoming a forecast.
        if (count < 4 || changes < 3 || tick - firstTick < 30 || firstEnergy - lastEnergy < 3) { return 0; }
        double denominator = count * sumTT - sumT * sumT;
        return denominator <= 0 ? 0 : Math.max(0, -(count * sumTE - sumT * sumE) / denominator);
    }
}

package com.wintertodtautopilot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Singleton
public class WintertodtRoundTracker
{
    private static final Pattern NUMBER = Pattern.compile("([0-9][0-9,]*)");
    @Inject private Client client;
    private RoundState previous = RoundState.OUTSIDE;
    private final WintertodtRoundForecast forecast = new WintertodtRoundForecast();
    private int completedAt = -1;
    private int finalPoints = -1;

    public void reset()
    {
        previous = RoundState.OUTSIDE;
        forecast.reset();
        completedAt = -1;
        finalPoints = -1;
    }
    public void fill(WintertodtSnapshot.WintertodtSnapshotBuilder b, boolean insidePrison, int lit)
    {
        int tick = client.getTickCount();
        // The current HUD puts "Wintertodt's Energy: 70%" in the bar title.
        // ENERGY is a legacy widget and can be hidden/empty in the live interface.
        int energy = readNumber(client.getWidget(InterfaceID.WintStatus.ENERGY_TITLE));
        if (energy < 0 || energy > 100)
        {
            energy = readNumber(client.getWidget(InterfaceID.WintStatus.ENERGY));
        }
        if (energy > 100) { energy = -1; }
        int points = readNumber(client.getWidget(InterfaceID.WintStatus.POINTS));
        int seconds = client.getVarbitValue(VarbitID.WINT_TRANSMIT_RESPAWNDELAY) * 30 / 50;
        RoundState state;
        if (!insidePrison) { state = RoundState.LOBBY; }
        else if (seconds > 0) { state = RoundState.COUNTDOWN; }
        else if (energy > 0) { state = RoundState.ACTIVE; }
        else { state = RoundState.COUNTDOWN; }
        boolean wasActive = previous == RoundState.ACTIVE || previous == RoundState.ENDING;
        if (insidePrison && wasActive && (energy == 0 || seconds > 0))
        {
            completedAt = tick;
            state = RoundState.COMPLETE;
        }
        if (insidePrison && completedAt >= 0 && tick - completedAt < 5 && energy <= 0)
        {
            state = RoundState.COMPLETE;
        }
        if (state == RoundState.ACTIVE && !wasActive)
        {
            forecast.reset(); completedAt = -1; finalPoints = -1;
        }
        EndUrgency urgency = EndUrgency.NORMAL;
        if (state == RoundState.ACTIVE)
        {
            if (points >= 0) { finalPoints = points; }
            urgency = classify(energy, tick, lit);
            if (urgency != EndUrgency.NORMAL) { state = RoundState.ENDING; }
        }
        else { forecast.reset(); }
        if (state == RoundState.COMPLETE && finalPoints >= 0)
        {
            finalPoints = Math.max(points, finalPoints);
            points = finalPoints;
        }
        b.roundState(state).wintertodtEnergy(energy).points(points).secondsToStart(seconds)
            .endUrgency(urgency).litBraziers(lit)
            .estimatedSecondsLeft(forecast.getSecondsLeft()).roundBudgetSeconds(forecast.getBudgetSeconds());
        previous = state;
    }
    EndUrgency classify(int energy, int tick, int lit)
    {
        forecast.observe(energy, tick, lit);
        double secondsLeft = forecast.getSecondsLeft() < 0 ? Double.POSITIVE_INFINITY : forecast.getSecondsLeft();
        // Energy cutoffs are conservative categories, not promises of an exact finish time.
        if (energy <= 3 || secondsLeft <= 10) { return EndUrgency.IMMINENT; }
        if (energy <= 12 && lit > 0 || secondsLeft <= 35) { return EndUrgency.ENDING_SOON; }
        return EndUrgency.NORMAL;
    }
    static int readNumber(Widget widget)
    {
        if (widget == null || widget.isHidden()) { return -1; }
        return parseNumber(widget.getText());
    }
    static int parseNumber(String text)
    {
        if (text == null) { return -1; }
        Matcher matcher = NUMBER.matcher(Text.removeTags(text));
        if (!matcher.find()) { return -1; }
        try { return Integer.parseInt(matcher.group(1).replace(",", "")); }
        catch (NumberFormatException e) { return -1; }
    }
}

package com.wintertodtautopilot;

/** Shared safety priority for both planners. */
final class WintertodtSafety
{
    private WintertodtSafety() { }
    static WintertodtObjective objective(WintertodtSnapshot s, PlannerSettings settings)
    {
        if (s.getRoundState() == RoundState.OUTSIDE || s.getRoundState() == RoundState.LOBBY
            || s.getWarmth() < 0 || s.getWarmth() > settings.getRestoreWarmth()
            || s.getCurrentActivity() == PlayerActivity.RESTORING_WARMTH) { return null; }
        boolean emergency = s.getWarmth() <= settings.getEmergencyWarmth();
        if (s.getWarmthItem() >= 0)
        {
            return new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
                (emergency ? "LOW WARMTH - " : "") + (WintertodtConstants.doses(s.getWarmthItem()) > 0
                    ? "Drink rejuvenation potion" : "Eat food to restore warmth"),
                "warmth_low", TargetKind.NONE, 1, emergency, s.getWarmthItem());
        }
        return new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
            "Move to the safe lobby - no warmth supplies", "no_warmth_supplies", TargetKind.DOOR, 0, true);
    }
}

package com.wintertodtautopilot;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class WintertodtSceneOverlay extends Overlay
{
    private final Client client;
    private final WintertodtAutopilotPlugin plugin;
    private final WintertodtAutopilotConfig config;
    private final ModelOutlineRenderer outlines;
    @Inject
    WintertodtSceneOverlay(Client client, WintertodtAutopilotPlugin plugin,
        WintertodtAutopilotConfig config, ModelOutlineRenderer outlines)
    {
        this.client = client; this.plugin = plugin; this.config = config; this.outlines = outlines;
        setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE);
    }
    @Override
    public Dimension render(Graphics2D graphics)
    {
        WintertodtObjective o = plugin.getObjective();
        WintertodtSnapshot s = plugin.getSnapshot();
        if (plugin.isPaused() || o == null || s.getRoundState() == RoundState.OUTSIDE
            || WintertodtGuidance.performing(s, o)) { return null; }
        Color color = WintertodtOverlay.color(o);
        float strength = WintertodtHighlight.strength(s, o, config.pulseInterruptions());
        if (config.highlightTarget())
        {
            NPC npc = plugin.getTargetNpc(); TileObject object = plugin.getTargetObject();
            int width = Math.max(1, Math.min(4, config.highlightBorderWidth()));
            Color outline = WintertodtHighlight.alpha(color, (int) (255 * strength));
            if (npc != null) { outlines.drawOutline(npc, width, outline, 1); }
            else if (object != null) { outlines.drawOutline(object, width, outline, 1); }
        }
        if (!config.showPath() && !config.highlightStandingTiles()) { return null; }
        // Isolate the clip: paths and floor markers must never paint over the UI.
        Graphics2D floor = (Graphics2D) graphics.create();
        try
        {
            floor.clip(new java.awt.Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
                client.getViewportWidth(), client.getViewportHeight()));
            List<WorldPoint> path = plugin.getPath();
            if (config.showPath())
            {
                Point previous = null;
                // Only join validated tile edges; do not bridge missing projections.
                for (WorldPoint step : path)
                {
                    LocalPoint local = LocalPoint.fromWorld(client, step);
                    Point next = local == null ? null : Perspective.localToCanvas(client, local, step.getPlane());
                    if (previous != null && next != null) { WintertodtHighlight.routeEdge(floor, previous, next, color, strength); }
                    previous = next;
                }
            }
            if (config.highlightStandingTiles())
            {
                WorldPoint destination = standingPoint(s, o, path);
                Polygon tile = destination == null ? null : tile(destination);
                if (tile != null)
                {
                    WintertodtHighlight.tile(floor, tile, color, strength, true);
                }
            }
        }
        finally { floor.dispose(); }
        return null;
    }
    private Polygon tile(WorldPoint point)
    {
        LocalPoint local = LocalPoint.fromWorld(client, point);
        return local == null ? null : Perspective.getCanvasTilePoly(client, local);
    }
    static WorldPoint standingPoint(WintertodtSnapshot s, WintertodtObjective o, List<WorldPoint> path)
    {
        if (o.getTarget() == TargetKind.NONE && s.getCurrentActivity() != PlayerActivity.MOVING
            && (o.getType() == ObjectiveType.FLETCH || o.getType() == ObjectiveType.MAKE_REJUVENATION))
        { return s.getPlayerLocation(); }
        return path.isEmpty() ? null : path.get(path.size() - 1);
    }
}

package com.wintertodtautopilot;

import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** One immutable observation. -1 denotes an unavailable numeric server/widget signal. */
@Value
@Builder(toBuilder = true)
public class WintertodtSnapshot
{
    @Builder.Default int observationTick = -1;
    @lombok.Singular private java.util.List<CornerObservation> corners;
    @Builder.Default RoundState roundState = RoundState.OUTSIDE;
    @Builder.Default int wintertodtEnergy = -1;
    @Builder.Default int warmth = -1;
    @Builder.Default int rawWarmth = -1;
    @Builder.Default int points = -1;
    @Builder.Default int secondsToStart = -1;
    int brumaRoots;
    int brumaKindling;
    @Builder.Default int firemakingLevel = 50;
    @Builder.Default int warmClothingCount = -1;
    int foodCount;
    int rejuvenationDoses;
    int unfinishedPotionCount;
    int brumaHerbCount;
    int freeSlots;
    @Builder.Default int runEnergyPercent = -1;
    @Builder.Default int warmthItem = -1;
    @Builder.Default int potionItem = -1;
    boolean hasKnife;
    boolean hasFletchingKnife;
    boolean hasHammer;
    boolean hasTinderbox;
    boolean hasBrumaTorch;
    boolean hasAxe;
    boolean canMixPotion;
    boolean localPyromancerKnown;
    boolean localPyromancerIncapacitated;
    @Builder.Default BrazierState localBrazierState = BrazierState.UNKNOWN;
    @Builder.Default PlayerActivity currentActivity = PlayerActivity.IDLE;
    boolean playerIdle;
    boolean interrupted;
    int inactiveTicks;
    WorldPoint playerLocation;
    @Builder.Default WorkingCorner workingCorner = WorkingCorner.AUTOMATIC;
    @Builder.Default EndUrgency endUrgency = EndUrgency.NORMAL;
    int litBraziers;
    @Builder.Default int estimatedSecondsLeft = -1;
    @Builder.Default int roundBudgetSeconds = -1;
    /** Walking tile distance to a usable adjacent tile; -1 if not observed. */
    @Builder.Default int brazierDistance = -1;
    @Builder.Default String interaction = "None";
    /** -1 means incomplete evidence; a loaded-object count is not global coverage. */
    public int observedGlobalLitBraziers()
    {
        java.util.EnumSet<WorkingCorner> seen = java.util.EnumSet.noneOf(WorkingCorner.class);
        int lit = 0;
        for (CornerObservation c : corners)
        {
            if (c.getCorner() == WorkingCorner.AUTOMATIC || !seen.add(c.getCorner())
                || c.getBrazierSource() == CornerObservation.Source.NONE || !c.brazierFresh(observationTick)
                || c.getBrazierState() == BrazierState.UNKNOWN || c.getBrazierState() == BrazierState.UNAVAILABLE)
            { return -1; }
            if (c.getBrazierState() == BrazierState.LIT) { ++lit; }
        }
        return seen.size() == 4 ? lit : -1;
    }
    public CornerObservation corner(WorkingCorner corner)
    {
        for (CornerObservation c : corners) { if (c.getCorner() == corner) { return c; } }
        return null;
    }
    public int inventoryPoints() { return brumaRoots * WintertodtConstants.ROOT_POINTS + brumaKindling * WintertodtConstants.KINDLING_POINTS; }
    public int potentialPointsIfFletched() { return (brumaRoots + brumaKindling) * WintertodtConstants.KINDLING_POINTS; }
    public int projectedPoints() { return points < 0 ? -1 : points + inventoryPoints(); }
    public boolean rewardThresholdReached() { return points >= 500; }
    public boolean active() { return roundState == RoundState.ACTIVE || roundState == RoundState.ENDING; }
}

package com.wintertodtautopilot;

import java.util.ArrayDeque;
import java.util.Deque;

/** Observed trend, independent of the mass countdown. Never predicts a recovery deadline. */
final class WintertodtSoloEnergyModel
{
    // Wiki advises avoiding relights around 8%; keep a two-point margin without waiting to 24%.
    static final int RECOVERY_TRIGGER = 10;
    static final int RECOVERY_EXIT = 12;
    enum Trend { UNKNOWN, DRAINING, RECOVERING, STABLE }
    private final Deque<int[]> samples = new ArrayDeque<>();
    private int lastTick = -1;
    private int recoverySince = -1;
    private int consecutiveRecoveryExit;
    private boolean recovering;
    private Trend trend = Trend.UNKNOWN;
    private boolean rapidDrop;

    void reset()
    {
        samples.clear(); lastTick = -1; recoverySince = -1; consecutiveRecoveryExit = 0;
        recovering = false; trend = Trend.UNKNOWN; rapidDrop = false;
    }
    void observe(int tick, int energy)
    {
        if (tick < 0 || energy < 0 || energy > 100) { invalidateTrend(); return; }
        if (tick <= lastTick)
        {
            if (tick == lastTick) { return; }
            reset();
        }
        if (lastTick >= 0 && tick - lastTick > 2) { invalidateTrend(); consecutiveRecoveryExit = 0; }
        lastTick = tick;
        samples.addLast(new int[]{tick, energy});
        while (!samples.isEmpty() && tick - samples.peekFirst()[0] > 17) { samples.removeFirst(); }
        trend = Trend.UNKNOWN; rapidDrop = false;
        if (!samples.isEmpty() && tick - samples.peekFirst()[0] >= 10)
        {
            int delta = energy - samples.peekFirst()[1];
            trend = delta < 0 ? Trend.DRAINING : delta > 0 ? Trend.RECOVERING : Trend.STABLE;
        }
        int recentPeak = energy;
        int previousEnergy = -1;
        for (int[] sample : samples)
        {
            if (tick - sample[0] > 6) { continue; }
            // A recovery increase ends the preceding drain episode.
            recentPeak = previousEnergy >= 0 && sample[1] > previousEnergy
                ? sample[1] : Math.max(recentPeak, sample[1]);
            previousEnergy = sample[1];
        }
        rapidDrop = recentPeak - energy > 2;
        if (energy <= RECOVERY_TRIGGER && !recovering)
        { recovering = true; recoverySince = tick; consecutiveRecoveryExit = 0; }
        if (recovering)
        {
            consecutiveRecoveryExit = energy >= RECOVERY_EXIT ? consecutiveRecoveryExit + 1 : 0;
            if (consecutiveRecoveryExit >= 3 && tick - recoverySince >= 3)
            { recovering = false; recoverySince = -1; consecutiveRecoveryExit = 0; }
        }
    }
    private void invalidateTrend() { samples.clear(); trend = Trend.UNKNOWN; rapidDrop = false; consecutiveRecoveryExit = 0; }
    boolean isRecovering() { return recovering; }
    boolean isRapidDrop() { return rapidDrop; }
    Trend getTrend() { return trend; }
}

package com.wintertodtautopilot;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/** Solo controller. Global evidence gates relighting; carried points never count as earned. */
public final class WintertodtSoloEngine implements WintertodtPlanner
{
    private final WintertodtSoloEnergyModel energy = new WintertodtSoloEnergyModel();
    private final WintertodtSoloSupplyPlan supplies = new WintertodtSoloSupplyPlan();
    @Getter private SoloPhase phase = SoloPhase.PREPARE;
    @Getter private String transitionReason = "initial";
    @Getter private boolean finishRequested;
    private boolean finishedRound;
    private boolean sawActive;
    private int pointGoal = 5000;
    private boolean reducingEnergy = true;
    private WorkingCorner route = WorkingCorner.AUTOMATIC;
    private ObjectiveType batch;
    private int batchTarget;
    private WorkingCorner home;
    private WorkingCorner finishAnchor = WorkingCorner.AUTOMATIC;
    private WorkingCorner finishSecondary = WorkingCorner.AUTOMATIC;
    private PlannerSettings previousSettings;

    public void configure(int pointGoal, boolean requestFinish)
    {
        this.pointGoal = Math.max(500, Math.min(100000, pointGoal));
        if (requestFinish && !finishedRound) { finishRequested = true; }
    }
    @Override public int getPreparationDoseTarget() { return supplies.getTarget(); }
    public String getEnergyTrend() { return energy.getTrend().name(); }
    @Override public void reset()
    {
        energy.reset(); supplies.reset(); phase = SoloPhase.PREPARE; transitionReason = "reset";
        finishRequested = false; finishedRound = false; sawActive = false; reducingEnergy = true;
        route = WorkingCorner.AUTOMATIC; batch = null; batchTarget = 0; home = null; previousSettings = null;
        finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC;
    }

    @Override public WintertodtObjective decide(WintertodtSnapshot s, PlannerSettings settings)
    {
        WorkingCorner selected = s.getWorkingCorner() == WorkingCorner.AUTOMATIC
            ? s.getPlayerLocation() == null ? WorkingCorner.SOUTHWEST : WorkingCorner.nearest(s.getPlayerLocation())
            : s.getWorkingCorner();
        if (!settings.equals(previousSettings))
        { previousSettings = settings; route = WorkingCorner.AUTOMATIC; batch = null; }
        // Automatic working-corner changes must not discard an opening/finish destination mid-walk.
        if (home != selected) { home = selected; batch = null; }
        // Only explicit completion/countdown evidence ends a session. A missing HUD is not a new round.
        if (s.getRoundState() == RoundState.COMPLETE
            || sawActive && s.getRoundState() == RoundState.COUNTDOWN && s.getSecondsToStart() > 0)
        {
            finishedRound = true; finishRequested = false; sawActive = false;
            reducingEnergy = true; energy.reset(); supplies.reset(); batch = null; route = WorkingCorner.AUTOMATIC;
        }
        if (s.active() && finishedRound)
        {
            finishedRound = false; finishRequested = false;
        }
        WintertodtObjective safety = WintertodtSafety.objective(s, settings);
        if (safety != null) { return safety; }
        if (!s.active())
        {
            if (s.getRoundState() == RoundState.OUTSIDE) { return waitFor("Waiting for Wintertodt", "outside"); }
            if (s.getRoundState() == RoundState.LOBBY)
            { return action(ObjectiveType.ENTER, "Enter the Wintertodt prison", "lobby", TargetKind.DOOR, home, 0, false); }
            if (s.getRoundState() == RoundState.COMPLETE)
            { setPhase(SoloPhase.PREPARE, "round_complete"); return action(ObjectiveType.ROUND_COMPLETE, "Round complete", "round_complete", TargetKind.NONE, home, 0, false); }
            if (sawActive && s.getSecondsToStart() <= 0)
            { setPhase(SoloPhase.REASSESS, "solo_hud_missing"); return waitFor("Waiting for current round observations", "solo_hud_missing"); }
            setPhase(SoloPhase.PREPARE, "solo_prepare");
            WintertodtObjective prep = supplies.prepare(s, settings, phase);
            return prep != null ? prep : action(ObjectiveType.POSITION, "Get ready at the " + home + " brazier",
                "countdown_position", TargetKind.BRAZIER, home, 0, false);
        }
        sawActive = true;
        if (s.getWintertodtEnergy() < 1 || s.getWintertodtEnergy() > 100 || s.getWarmth() < 0 || s.getObservationTick() < 0 || s.getPoints() < 0 && !finishRequested)
        {
            energy.observe(s.getObservationTick(), -1);
            setPhase(SoloPhase.REASSESS, "solo_signals_unknown");
            return waitFor("Check energy, points and warmth observations", "solo_signals_unknown");
        }
        energy.observe(s.getObservationTick(), s.getWintertodtEnergy());
        boolean finish = finishRequested || s.getPoints() >= pointGoal;
        if (finish) { setPhase(SoloPhase.FINISH, finishRequested ? "solo_finish_requested" : "solo_goal_earned"); }
        else if (energy.isRecovering()) { setPhase(SoloPhase.RECOVER_ENERGY, "solo_energy_low"); }
        else
        {
            if (s.getWintertodtEnergy() <= 28) { reducingEnergy = false; }
            else if (s.getWintertodtEnergy() > 35) { reducingEnergy = true; }
            setPhase(reducingEnergy ? SoloPhase.REDUCE_ENERGY : SoloPhase.SUSTAIN,
                reducingEnergy ? "solo_opening" : "solo_energy_band");
        }
        // Feed promptly on an unexplained rapid drop, without claiming another player is responsible.
        if (!finish && phase != SoloPhase.REDUCE_ENERGY && energy.isRapidDrop() && fuel(s) > 0)
        {
            WorkingCorner lit = nearestLit(s);
            if (lit != WorkingCorner.AUTOMATIC)
            {
                setPhase(SoloPhase.REASSESS, "solo_rapid_drain");
                return feed(s, lit, "solo_rapid_drain", true);
            }
        }
        // Converting fuel is separate from controlling energy. Feed an already lit home even during recovery.
        if (fuel(s) > 0 && (finish || s.projectedPoints() >= pointGoal))
        {
            WorkingCorner lit = nearestLit(s);
            if (lit != WorkingCorner.AUTOMATIC) { return feed(s, lit, finish ? "solo_finish_feed" : "solo_goal_feed", finish); }
        }
        WintertodtObjective prep = supplies.prepare(s, settings, phase);
        if (prep != null)
        {
            if ("supply_inventory_blocked".equals(prep.getReason()) && fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC)
            { return feed(s, nearestLit(s), "solo_supply_space", false); }
            if ("supply_inventory_blocked".equals(prep.getReason()) && fuel(s) > 0
                && s.isHasHammer() && (s.isHasTinderbox() || s.isHasBrumaTorch())
                && (finish || !energy.isRecovering() && s.getWintertodtEnergy() > WintertodtSoloEnergyModel.RECOVERY_TRIGGER))
            {
                CornerObservation local = s.corner(home);
                if (local != null && local.getPyromancerState() == CornerObservation.PyromancerState.ALIVE)
                {
                    WintertodtObjective maintenance = maintain(s, home, finish);
                    if (maintenance != null) { return maintenance; }
                }
            }
            if (phase == SoloPhase.REDUCE_ENERGY) { setPhase(SoloPhase.PREPARE, "solo_prepare"); }
            return prep;
        }
        if (!finish && (phase == SoloPhase.RECOVER_ENERGY
            || s.getWintertodtEnergy() <= WintertodtSoloEnergyModel.RECOVERY_TRIGGER))
        {
            if (fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC && (s.getBrumaRoots() == 0 && s.getBrumaKindling() > 0 || !settings.fletch(s)))
            { return feed(s, nearestLit(s), "solo_recovery_feed", false); }
            WintertodtObjective healing = pointsHealing(s, settings, true);
            if (healing != null) { return healing; }
            return productive(s, settings, true);
        }
        if (phase == SoloPhase.REDUCE_ENERGY || phase == SoloPhase.FINISH)
        {
            WorkingCorner destination = phase == SoloPhase.FINISH ? finishCorner(s) : maintenanceCorner(s);
            if (destination != WorkingCorner.AUTOMATIC)
            {
                WintertodtObjective maintenance = maintain(s, destination, true);
                if (maintenance != null) { return maintenance; }
            }
            if (phase == SoloPhase.FINISH)
            {
                if (fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC)
                { return feed(s, nearestLit(s), "solo_finish_feed", true); }
                return waitFor("Finish requested - maintain drain until the round ends", "solo_finish_drain");
            }
        }
        else
        {
            WintertodtObjective healing = pointsHealing(s, settings, false);
            if (healing != null) { return healing; }
            WintertodtObjective maintenance = maintain(s, home, false);
            if (maintenance != null) { return maintenance; }
        }
        return productive(s, settings, false);
    }

    private WintertodtObjective maintain(WintertodtSnapshot s, WorkingCorner destination, boolean multi)
    {
        CornerObservation c = s.corner(destination);
        if (c == null || !c.brazierFresh(s.getObservationTick()) || !c.isBrazierVisible()
            || c.getBrazierState() == BrazierState.UNKNOWN)
        { return position(destination, "Move to observe the " + destination + " brazier", "solo_observe_corner"); }
        if (c.getBrazierState() == BrazierState.LIT)
        {
            if (c.isPyromancerVisible() && c.pyromancerFresh(s.getObservationTick())
                && c.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED)
            {
                if (s.observedGlobalLitBraziers() < 0)
                { setPhase(SoloPhase.REASSESS, "solo_coverage_unknown"); return waitFor("Check all brazier indicators before restoring drain", "solo_coverage_unknown"); }
                return heal(s, destination);
            }
            return null;
        }
        // Repairs and healing can restart drain too; hold them during the low-energy lockout.
        if (phase != SoloPhase.FINISH && (s.getWintertodtEnergy() <= WintertodtSoloEnergyModel.RECOVERY_TRIGGER || energy.isRecovering()))
        { return waitFor("Let energy recover - do not relight", "solo_recovery_wait"); }
        if (s.observedGlobalLitBraziers() < 0)
        {
            setPhase(SoloPhase.REASSESS, "solo_coverage_unknown");
            return waitFor("Check all brazier indicators before relighting", "solo_coverage_unknown");
        }
        if (!multi)
        {
            for (CornerObservation other : s.getCorners())
            {
                if (other.getCorner() != home && other.getBrazierState() == BrazierState.LIT)
                { return productiveRecovery(s); }
            }
        }
        if (!c.isPyromancerVisible() || !c.pyromancerFresh(s.getObservationTick())
            || c.getPyromancerState() == CornerObservation.PyromancerState.UNKNOWN)
        { return position(destination, "Move closer to observe the " + destination + " pyromancer", "solo_observe_pyromancer"); }
        if (c.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED) { return heal(s, destination); }
        if (c.getBrazierState() == BrazierState.BROKEN)
        { return action(ObjectiveType.REPAIR, "Repair the " + destination + " brazier", "solo_repair", TargetKind.BRAZIER, destination, 0, false, ItemID.HAMMER); }
        return action(ObjectiveType.LIGHT, "Light the " + destination + " brazier", "solo_light",
            TargetKind.BRAZIER, destination, 0, false, ItemID.TINDERBOX, ItemID.WINT_TORCH, ItemID.WINT_TORCH_OFFHAND);
    }

    private WintertodtObjective heal(WintertodtSnapshot s, WorkingCorner destination)
    {
        if (s.getRejuvenationDoses() <= 1)
        { return waitFor("Keep the last dose for warmth - prepare more potions", "solo_heal_reserve"); }
        return action(ObjectiveType.HEAL_PYROMANCER, "Heal the " + destination + " pyromancer", "solo_heal",
            TargetKind.PYROMANCER, destination, 1, false, s.getPotionItem());
    }
    private WintertodtObjective productiveRecovery(WintertodtSnapshot s)
    {
        WorkingCorner lit = nearestLit(s);
        if (fuel(s) > 0 && lit != WorkingCorner.AUTOMATIC && (s.getBrumaRoots() == 0 && s.getBrumaKindling() > 0 || !previousSettings.fletch(s)))
        { return feed(s, lit, "solo_remote_feed", false); }
        return unlitWork(s, previousSettings, false);
    }
    private WintertodtObjective unlitWork(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        boolean fletching = settings.fletch(s);
        if (batch == ObjectiveType.FLETCH && (s.getBrumaRoots() == 0 || !fletching)) { batch = null; }
        int carried = fletching ? s.potentialPointsIfFletched() : s.inventoryPoints();
        int remainingPoints = Math.max(0, pointGoal - s.getPoints() - carried);
        boolean processRoots = s.getBrumaRoots() > 0 && fletching
            && (s.getFreeSlots() == 0 || (s.getBrumaKindling() > 0 && batch != ObjectiveType.CHOP) || remainingPoints == 0
                || batch == ObjectiveType.FLETCH || s.getCurrentActivity() == PlayerActivity.FLETCHING);
        if (processRoots)
        {
            batch = ObjectiveType.FLETCH;
            return fletch(s, recovery ? "solo_recovery_fletch" : "solo_remote_lit");
        }
        if (s.getFreeSlots() > 0 && remainingPoints > 0)
        {
            batch = ObjectiveType.CHOP;
            int unit = fletching ? 25 : 10;
            int count = Math.min(s.getFreeSlots(), (remainingPoints + unit - 1) / unit);
            // Recovery and remote-brazier work share the sustain batch. Carry its
            // total target across the relight so it cannot collapse to one root.
            batchTarget = fuel(s) + count;
            return chop(s, count,
                recovery ? "solo_recovery_chop" : "solo_remote_lit");
        }
        return waitFor(recovery ? "Let energy recover to 12% - do not relight" : "Remote brazier is lit - leave home unlit",
            recovery ? "solo_recovery_wait" : "solo_remote_lit");
    }

    private WintertodtObjective productive(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        if (recovery) { return unlitWork(s, settings, true); }
        if (batch == ObjectiveType.FEED && fuel(s) == 0) { batch = null; }
        if (batch == ObjectiveType.FLETCH && (s.getBrumaRoots() == 0 || !settings.fletch(s))) { batch = ObjectiveType.FEED; }
        if (batch == ObjectiveType.CHOP && (fuel(s) >= batchTarget || s.getFreeSlots() == 0))
        { batch = settings.fletch(s) && s.getBrumaRoots() > 0 ? ObjectiveType.FLETCH : ObjectiveType.FEED; }
        if (batch == null)
        {
            if (s.getBrumaKindling() > 0 || fuel(s) > 0 && (s.getFreeSlots() == 0
                || s.getPoints() >= 0 && s.getPoints() + (settings.fletch(s) ? s.potentialPointsIfFletched() : s.inventoryPoints()) >= pointGoal))
            { batch = settings.fletch(s) && s.getBrumaRoots() > 0 ? ObjectiveType.FLETCH : ObjectiveType.FEED; }
            else
            {
                batch = ObjectiveType.CHOP;
                int capacity = fuel(s) + s.getFreeSlots();
                int needed = s.getPoints() < 0 ? capacity : Math.max(1, (pointGoal - s.getPoints() + (settings.fletch(s) ? 24 : 9)) / (settings.fletch(s) ? 25 : 10));
                batchTarget = Math.min(capacity, needed);
            }
        }
        if (batch == ObjectiveType.FLETCH) { return fletch(s, "solo_batch_fletch"); }
        if (batch == ObjectiveType.FEED && fuel(s) > 0) { return feed(s, home, "solo_batch_feed", false); }
        if (s.getFreeSlots() == 0) { return waitFor("Make space for bruma roots", "inventory_blocked"); }
        return chop(s, Math.max(1, batchTarget - fuel(s)), "solo_batch_chop");
    }
    private WintertodtObjective fletch(WintertodtSnapshot s, String reason)
    {
        // Fletching is allowed at roots and while running; only the safe preparation area forbids it.
        if (s.getPlayerLocation() != null && s.getPlayerLocation().getY() < 3988)
        { return position(home, "Leave the preparation area to fletch", "solo_fletch_inside"); }
        return action(ObjectiveType.FLETCH, "Fletch " + s.getBrumaRoots() + " roots", reason,
            TargetKind.NONE, home, s.getBrumaRoots(), false, ItemID.KNIFE, ItemID.FLETCHING_KNIFE, ItemID.WINT_BRUMA_ROOT);
    }
    private WintertodtObjective chop(WintertodtSnapshot s, int count, String reason)
    { return action(ObjectiveType.CHOP, "Chop " + count + " bruma root" + (count == 1 ? "" : "s"), reason, TargetKind.ROOTS, home, count, false); }
    private WintertodtObjective feed(WintertodtSnapshot s, WorkingCorner destination, String reason, boolean urgent)
    { return action(ObjectiveType.FEED, "Feed fuel at the " + destination + " brazier", reason, TargetKind.BRAZIER, destination, fuel(s), urgent, s.getBrumaKindling() > 0 ? ItemID.WINT_BRUMA_KINDLING : ItemID.WINT_BRUMA_ROOT); }
    private WintertodtObjective position(WorkingCorner destination, String text, String reason)
    { return action(ObjectiveType.POSITION, text, reason, TargetKind.BRAZIER, destination, 0, false); }
    private WintertodtObjective waitFor(String text, String reason)
    { return action(ObjectiveType.WAIT, text, reason, TargetKind.NONE, home == null ? WorkingCorner.SOUTHWEST : home, 0, false); }
    private WintertodtObjective action(ObjectiveType type, String text, String reason, TargetKind target,
        WorkingCorner destination, int count, boolean urgent, int... items)
    { return new WintertodtObjective(type, text, reason, target, destination, count, urgent, items); }
    private void setPhase(SoloPhase next, String reason)
    {
        if (phase != next)
        {
            phase = next; transitionReason = reason; route = WorkingCorner.AUTOMATIC;
            if (next != SoloPhase.FINISH)
            { finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC; }
        }
    }
    private static int fuel(WintertodtSnapshot s) { return s.getBrumaRoots() + s.getBrumaKindling(); }
    private WorkingCorner nearestLit(WintertodtSnapshot s)
    {
        WorkingCorner result = WorkingCorner.AUTOMATIC;
        int distance = Integer.MAX_VALUE;
        for (CornerObservation c : s.getCorners())
        {
            if (c.getBrazierState() != BrazierState.LIT || !c.isBrazierVisible() || !c.brazierFresh(s.getObservationTick())) { continue; }
            int d = s.getPlayerLocation() == null ? (c.getCorner() == home ? 0 : 100) : s.getPlayerLocation().distanceTo(c.getCorner().location());
            if (d < distance) { result = c.getCorner(); distance = d; }
        }
        return result;
    }
    private WintertodtObjective pointsHealing(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        if (settings.getStrategy() == WintertodtStrategy.MASS_XP || s.getRejuvenationDoses() <= 1) { return null; }
        // Optional remote healing fits the processing stage, not each newly chopped root.
        boolean roaming = s.getBrumaRoots() > 0 && (batch == ObjectiveType.FLETCH
            || s.getCurrentActivity() == PlayerActivity.FLETCHING || s.getFreeSlots() == 0);
        WorkingCorner target = WorkingCorner.AUTOMATIC;
        int distance = Integer.MAX_VALUE;
        for (CornerObservation c : s.getCorners())
        {
            if (!c.isPyromancerVisible() || !c.pyromancerFresh(s.getObservationTick())
                || c.getPyromancerHealthPercent() < 0 || c.getPyromancerHealthPercent() >= 100
                || c.getPyromancerState() == CornerObservation.PyromancerState.UNKNOWN) { continue; }
            // Healing an incapacitated pyro at a lit brazier would restart drain during recovery.
            if (recovery && (!c.brazierFresh(s.getObservationTick())
                || c.getBrazierState() != BrazierState.UNLIT && c.getBrazierState() != BrazierState.BROKEN)) { continue; }
            if (c.getCorner() != home && (!roaming || s.getRunEnergyPercent() >= 0 && s.getRunEnergyPercent() <= 10)) { continue; }
            if (!recovery && c.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED
                && c.getBrazierState() == BrazierState.LIT && s.observedGlobalLitBraziers() < 0) { continue; }
            int d = c.getCorner() == home ? 0 : s.getPlayerLocation() == null ? 100
                : s.getPlayerLocation().distanceTo(c.getCorner().location());
            if (d < distance) { distance = d; target = c.getCorner(); }
        }
        return target == WorkingCorner.AUTOMATIC ? null : action(ObjectiveType.HEAL_PYROMANCER,
            "Heal the " + target + " pyromancer", "solo_points_heal", TargetKind.PYROMANCER, target, 1, false, s.getPotionItem());
    }

    private WorkingCorner finishCorner(WintertodtSnapshot s)
    {
        if (finishAnchor == WorkingCorner.AUTOMATIC)
        {
            finishAnchor = home;
            int best = Integer.MAX_VALUE;
            for (WorkingCorner c : WorkingCorner.values())
            {
                if (c == WorkingCorner.AUTOMATIC || c == finishAnchor
                    || c.location().getX() != finishAnchor.location().getX() && c.location().getY() != finishAnchor.location().getY()) { continue; }
                CornerObservation observation = s.corner(c);
                int distance = s.getPlayerLocation() == null ? 100 : s.getPlayerLocation().distanceTo(c.location());
                if (observation != null && observation.brazierFresh(s.getObservationTick()) && observation.getBrazierState() == BrazierState.LIT)
                { distance -= 1000; }
                if (distance < best) { best = distance; finishSecondary = c; }
            }
        }
        boolean lowRun = s.getRunEnergyPercent() >= 0 && s.getRunEnergyPercent() <= 10;
        WorkingCorner anchor = lowRun ? home : finishAnchor;
        for (WorkingCorner c : lowRun ? new WorkingCorner[]{anchor} : new WorkingCorner[]{anchor, finishSecondary})
        {
            CornerObservation observation = s.corner(c);
            if (observation == null || !observation.brazierFresh(s.getObservationTick()) || observation.getBrazierState() != BrazierState.LIT
                || observation.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED) { return c; }
        }
        return WorkingCorner.AUTOMATIC;
    }

    private WorkingCorner maintenanceCorner(WintertodtSnapshot s)
    {
        CornerObservation current = s.corner(route);
        if (route != WorkingCorner.AUTOMATIC && (current == null || current.getBrazierState() != BrazierState.LIT
            || current.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED)) { return route; }
        route = WorkingCorner.AUTOMATIC;
        int distance = Integer.MAX_VALUE;
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c == WorkingCorner.AUTOMATIC) { continue; }
            CornerObservation observation = s.corner(c);
            if (observation != null && observation.brazierFresh(s.getObservationTick())
                && observation.getBrazierState() == BrazierState.LIT
                && observation.getPyromancerState() != CornerObservation.PyromancerState.INCAPACITATED) { continue; }
            int d = s.getPlayerLocation() == null ? (c == home ? 0 : 100) : s.getPlayerLocation().distanceTo(c.location());
            if (d < distance) { route = c; distance = d; }
        }
        return route;
    }
}

package com.wintertodtautopilot;

import net.runelite.api.gameval.ItemID;

/** A replenished working reserve, never a promise to cover an unlimited Solo session. */
final class WintertodtSoloSupplyPlan
{
    private int target;
    private boolean restocking = true;
    int getTarget() { return target; }
    void reset() { target = 0; restocking = true; }

    WintertodtObjective prepare(WintertodtSnapshot s, PlannerSettings settings, SoloPhase phase)
    {
        TargetKind tool = phase != SoloPhase.FINISH && !s.isHasAxe() ? TargetKind.AXE_CRATE : !s.isHasHammer() ? TargetKind.HAMMER_CRATE
            : phase != SoloPhase.FINISH && WintertodtGuidance.needsKnife(settings) && !s.isHasKnife() ? TargetKind.KNIFE_CRATE
            : !s.isHasTinderbox() && !s.isHasBrumaTorch() ? TargetKind.TINDERBOX_CRATE : TargetKind.NONE;
        if (tool != TargetKind.NONE)
        {
            if (s.getFreeSlots() == 0) { return blocked("tools"); }
            return new WintertodtObjective(ObjectiveType.GET_TOOL, WintertodtGuidance.supplyInstruction(tool, 1),
                "prepare_tools", tool, 1, false);
        }
        int reserve = phase == SoloPhase.FINISH ? 8 : 24;
        int restockAt = phase != SoloPhase.FINISH && settings.getStrategy() != WintertodtStrategy.MASS_XP ? 8 : 4;
        if (!restocking && s.getRejuvenationDoses() < restockAt) { restocking = true; target = reserve; }
        if (target == 0) { target = reserve; }
        if (phase == SoloPhase.FINISH) { target = Math.min(target, reserve); }
        if (s.getRejuvenationDoses() >= target) { restocking = false; }
        if (!restocking) { return null; }
        return ingredients(s, Math.max(1, (target - s.getRejuvenationDoses() + 3) / 4));
    }
    private WintertodtObjective ingredients(WintertodtSnapshot s, int bottles)
    {
        if (s.getUnfinishedPotionCount() > 0 && s.getBrumaHerbCount() > 0)
        {
            int count = Math.min(bottles, Math.min(s.getUnfinishedPotionCount(), s.getBrumaHerbCount()));
            return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
                s.isCanMixPotion() ? "Mix " + count + " potion" + (count == 1 ? "" : "s")
                    : WintertodtGuidance.supplyInstruction(TargetKind.BREWMA, count),
                "mix_rejuvenation", s.isCanMixPotion() ? TargetKind.NONE : TargetKind.BREWMA,
                count, false, ItemID.WINT_HERB, ItemID.WINT_VIAL);
        }
        if (s.getFreeSlots() == 0) { return blocked("potion ingredients"); }
        boolean vial = s.getUnfinishedPotionCount() < bottles
            && (s.getFreeSlots() > 1 || s.getUnfinishedPotionCount() == 0 || s.getBrumaHerbCount() > 0);
        int capacity = vial && s.getBrumaHerbCount() == 0 ? s.getFreeSlots() - 1 : s.getFreeSlots();
        if (capacity <= 0) { return blocked("potion ingredients"); }
        int count = Math.min(capacity, vial ? bottles - s.getUnfinishedPotionCount() : Math.max(1, bottles - s.getBrumaHerbCount()));
        TargetKind target = vial ? TargetKind.POTION_CRATE : TargetKind.HERBS;
        return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
            WintertodtGuidance.supplyInstruction(target, count), "solo_restock", target, count, false);
    }
    private WintertodtObjective blocked(String resource)
    {
        return new WintertodtObjective(ObjectiveType.WAIT, "Make space for " + resource,
            "supply_inventory_blocked", TargetKind.NONE, 0, false);
    }
}

package com.wintertodtautopilot;

import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

@Singleton
public class WintertodtStateTracker
{
    @Inject private Client client;
    @Inject private WintertodtInventoryTracker inventory;
    @Inject private WintertodtObjectTracker objects;
    @Inject private WintertodtNpcTracker npcs;
    @Inject private WintertodtRoundTracker rounds;
    private final WintertodtCornerTracker corners = new WintertodtCornerTracker();
    private PlayerActivity activity = PlayerActivity.IDLE;
    private int lastActionTick = -100;
    private int interruptedAt = -100;
    private boolean interrupted;
    private WorldPoint clickedCorner;
    private Boolean canMixPotion;
    private WintertodtSnapshot previous = WintertodtSnapshot.builder().build();

    public WintertodtSnapshot snapshot(WorkingCorner configured)
    {
        Player player = client.getLocalPlayer();
        if (player == null || player.getWorldLocation().getRegionID() != WintertodtConstants.REGION)
        {
            reset();
            return previous;
        }
        int tick = client.getTickCount();
        WorldPoint location = player.getWorldLocation();
        WorkingCorner corner = objects.select(location, configured, clickedCorner);
        clickedCorner = null;
        if (canMixPotion == null) { canMixPotion = Quest.DRUIDIC_RITUAL.getState(client) == QuestState.FINISHED; }
        WintertodtSnapshot.WintertodtSnapshotBuilder b = WintertodtSnapshot.builder().playerLocation(location)
            .workingCorner(corner).localBrazierState(objects.brazier(location))
            .brazierDistance(objects.brazierDistance(player))
            .canMixPotion(canMixPotion).firemakingLevel(client.getRealSkillLevel(Skill.FIREMAKING));
        int runEnergy = client.getEnergy();
        b.runEnergyPercent(runEnergy >= 0 && runEnergy <= 10000 ? runEnergy / 100 : -1);
        inventory.fill(b);
        // Region 6462 includes the safe preparation area INSIDE the Doors of Dinh.
        // Do not mistake that area for an outside lobby when joining mid-round.
        rounds.fill(b, true, objects.litCount());
        WintertodtSnapshot partial = b.build();
        boolean boundary = partial.active() != previous.active();
        if (boundary)
        {
            activity = PlayerActivity.IDLE;
            interrupted = false;
            lastActionTick = tick;
        }
        if (boundary) { corners.reset(); }
        b.observationTick(tick).corners(corners.observe(tick, objects, npcs, partial.active() ? client : null));
        int rawWarmth = client.getVarbitValue(VarbitID.WINT_WARMTH);
        int warmth = rawWarmth >= 0 && rawWarmth <= 1000 && (partial.active() || rawWarmth > 0) ? rawWarmth / 10 : -1;
        NPC pyro = npcs.target(TargetKind.PYROMANCER, corner.location());
        b.warmth(warmth).rawWarmth(rawWarmth).localPyromancerKnown(pyro != null)
            .localPyromancerIncapacitated(pyro != null && WintertodtNpcTracker.id(pyro) == NpcID.WINT_WIZARD_DOWN);
        boolean moving = previous.getPlayerLocation() != null && !location.equals(previous.getPlayerLocation());
        PlayerActivity animation = WintertodtConstants.activity(player.getAnimation());
        if (tick - interruptedAt > 1 && animation != PlayerActivity.IDLE) { setActivity(animation); }
        boolean bagChanged = inventory.changed();
        if (!boundary && partial.active())
        {
            if (partial.getBrumaRoots() > previous.getBrumaRoots()) { setActivity(PlayerActivity.CHOPPING); }
            else if (partial.getBrumaKindling() > previous.getBrumaKindling()
                && partial.getBrumaRoots() < previous.getBrumaRoots()) { setActivity(PlayerActivity.FLETCHING); }
            else if (partial.getPoints() > previous.getPoints()
                && partial.getBrumaRoots() + partial.getBrumaKindling() < previous.getBrumaRoots() + previous.getBrumaKindling())
            { setActivity(PlayerActivity.FEEDING); }
            if (partial.getRejuvenationDoses() > previous.getRejuvenationDoses()
                && partial.getUnfinishedPotionCount() < previous.getUnfinishedPotionCount()) { setActivity(PlayerActivity.MAKING_POTION); }
            if (warmth > previous.getWarmth() + 10 && bagChanged) { setActivity(PlayerActivity.RESTORING_WARMTH); }
        }
        if (moving) { lastActionTick = tick; }
        if (activity == PlayerActivity.FLETCHING && partial.getBrumaRoots() == 0
            || activity == PlayerActivity.FEEDING && partial.getBrumaRoots() + partial.getBrumaKindling() == 0
            || tick - lastActionTick >= 5)
        {
            activity = PlayerActivity.IDLE;
        }
        Actor interaction = player.getInteracting();
        boolean idle = !moving && activity == PlayerActivity.IDLE && interaction == null && tick - lastActionTick >= 5;
        b.currentActivity(moving ? PlayerActivity.MOVING : activity).playerIdle(idle).interrupted(interrupted)
            .inactiveTicks(Math.max(0, tick - lastActionTick))
            .interaction(interaction == null || interaction.getName() == null ? "None" : interaction.getName());
        previous = b.build();
        return previous;
    }
    public void animation(Actor actor)
    {
        if (actor != client.getLocalPlayer() || previous.getRoundState() == RoundState.OUTSIDE) { return; }
        PlayerActivity observed = WintertodtConstants.activity(actor.getAnimation());
        if (observed != PlayerActivity.IDLE && client.getTickCount() - interruptedAt > 1) { setActivity(observed); }
    }
    private void setActivity(PlayerActivity value)
    {
        activity = value;
        lastActionTick = client.getTickCount();
        interrupted = false;
    }
    public void clicked(MenuOptionClicked event)
    {
        if (previous.getRoundState() == RoundState.OUTSIDE) { return; }
        lastActionTick = client.getTickCount();
        String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
        String target = Text.removeTags(event.getMenuTarget()).toLowerCase(Locale.ROOT);
        if (target.contains("bruma root") || target.contains("brazier"))
        {
            MenuAction action = event.getMenuAction();
            if (action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
                || action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION)
            {
                clickedCorner = WorldPoint.fromScene(client.getTopLevelWorldView(), event.getParam0(), event.getParam1(), client.getTopLevelWorldView().getPlane());
            }
        }
        if (option.equals("eat") || option.equals("drink") && target.contains("rejuvenation")) { setActivity(PlayerActivity.RESTORING_WARMTH); }
        else if (target.contains("pyromancer") && (option.equals("help") || option.equals("use"))) { setActivity(PlayerActivity.HEALING); }
    }
    public void chat(ChatMessage event)
    {
        if (!previous.active() || event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) { return; }
        String text = Text.removeTags(event.getMessage());
        if (text.startsWith("You carefully fletch the root")) { setActivity(PlayerActivity.FLETCHING); return; }
        boolean damage = text.startsWith("The cold of") || text.startsWith("The freezing cold attack")
            || text.startsWith("The brazier is broken and shrapnel");
        boolean stopped = text.startsWith("You have run out of bruma roots") || text.startsWith("Your inventory is too full")
            || text.startsWith("The brazier has gone out.");
        if (stopped || damage && activity != PlayerActivity.CHOPPING && activity != PlayerActivity.IDLE)
        {
            activity = PlayerActivity.IDLE;
            interrupted = true;
            interruptedAt = client.getTickCount();
            // Grace period still protects idle emphasis from animation gaps.
            lastActionTick = interruptedAt - 3;
        }
        if (text.startsWith("You fix the brazier") || text.startsWith("You light the brazier"))
        {
            activity = PlayerActivity.IDLE; lastActionTick = client.getTickCount();
        }
    }
    public void reset()
    {
        activity = PlayerActivity.IDLE; lastActionTick = -100; interruptedAt = -100;
        interrupted = false; clickedCorner = null; canMixPotion = null;
        previous = WintertodtSnapshot.builder().build();
        inventory.reset(); rounds.reset(); objects.resetCorner(); corners.reset();
    }
}

