    private static void render(Graphics2D graphics, int x, int y, WintertodtSnapshot snapshot,
        WintertodtObjective objective, WintertodtAutopilotConfig config)
    {
        WintertodtAutopilotPlugin plugin = mock(WintertodtAutopilotPlugin.class);
        when(plugin.getPotionTargetDoses()).thenReturn(config.mode() == WintertodtMode.SOLO ? config.finishSoloRound() ? 8 : 24 : 4);
        when(plugin.getSoloPhase()).thenReturn(config.finishSoloRound() ? SoloPhase.FINISH
            : objective.getReason().contains("recovery") ? SoloPhase.RECOVER_ENERGY
            : objective.getReason().contains("unknown") ? SoloPhase.REASSESS : SoloPhase.SUSTAIN);
        when(plugin.getSoloEnergyTrend()).thenReturn("STABLE");
        when(plugin.isSoloFinishRequested()).thenReturn(config.finishSoloRound());
        when(plugin.isPaused()).thenReturn(config.pauseGuidance());
        when(plugin.getSnapshot()).thenReturn(snapshot); when(plugin.getObjective()).thenReturn(objective);
        WintertodtOverlay overlay = new WintertodtOverlay(plugin, config);
        Graphics2D local = (Graphics2D) graphics.create(); local.translate(x, y); local.setFont(FontManager.getRunescapeFont());
        // RuneLite's panel caches child dimensions for its next frame.
        overlay.render(local); overlay.render(local); overlay.render(local); local.dispose();
    }
}

package com.wintertodtautopilot;

import java.util.List;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtPathTrackerTest
{
    @Test public void resolvesFootprintCachesAndInvalidatesCollisionChanges() throws Exception
    {
        Client client = mock(Client.class); Player player = mock(Player.class);
        WorldView view = mock(WorldView.class); CollisionData collision = mock(CollisionData.class);
        when(client.getLocalPlayer()).thenReturn(player); when(client.getTopLevelWorldView()).thenReturn(view);
        when(view.getBaseX()).thenReturn(1600); when(view.getBaseY()).thenReturn(3968);
        when(view.getSizeX()).thenReturn(8); when(view.getSizeY()).thenReturn(8);
        when(view.getCollisionMaps()).thenReturn(new CollisionData[]{collision});
        when(player.getWorldLocation()).thenReturn(new WorldPoint(1601, 3969, 0));
        LocalPoint start = LocalPoint.fromScene(1, 1, view);
        when(player.getLocalLocation()).thenReturn(start);
        int[][] flags = new int[8][8];
        for (int x = 4; x <= 5; x++) { for (int y = 4; y <= 5; y++) { flags[x][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; } }
        when(collision.getFlags()).thenReturn(flags);
        GameObject object = mock(GameObject.class);
        when(object.getSceneMinLocation()).thenReturn(new Point(4, 4));
        when(object.getSceneMaxLocation()).thenReturn(new Point(5, 5));
        WintertodtPathTracker tracker = new WintertodtPathTracker(); TrackerTestSupport.inject(tracker, "client", client);
        TrackerTestSupport.inject(tracker, "config", new WintertodtAutopilotConfig() {});
        WorldPoint target = new WorldPoint(1605, 3973, 0);
        tracker.update(target, object, null, true);
        List<WorldPoint> route = tracker.getPath(); assertFalse(route.isEmpty());
        WorldPoint end = route.get(route.size()-1);
        assertTrue(end.getX() == 1603 || end.getY() == 3971);
        tracker.update(target, object, null, true); assertSame(route, tracker.getPath());
        flags[2][1] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        tracker.invalidate(); tracker.update(target, object, null, true);
        assertFalse(tracker.getPath().contains(new WorldPoint(1602, 3969, 0)));
        tracker.update(target, object, null, false); assertTrue(tracker.getPath().isEmpty());
        tracker.update(target, object, null, true); tracker.reset(); assertTrue(tracker.getPath().isEmpty());
    }
    @Test public void soloGapRoutesBothWaysAndRechecksLevelAndModeImmediately() throws Exception
    {
        Client client = mock(Client.class); Player player = mock(Player.class);
        WorldView view = mock(WorldView.class); CollisionData collision = mock(CollisionData.class);
        WintertodtAutopilotConfig config = mock(WintertodtAutopilotConfig.class);
        when(client.getLocalPlayer()).thenReturn(player); when(client.getTopLevelWorldView()).thenReturn(view);
        when(view.getBaseX()).thenReturn(1620); when(view.getBaseY()).thenReturn(4000);
        when(view.getSizeX()).thenReturn(24); when(view.getSizeY()).thenReturn(32);
        when(view.getCollisionMaps()).thenReturn(new CollisionData[]{collision});
        int[][] flags = new int[24][32];
        // Northern chasm: the southern walking route stays open, with three separated pillars.
        for (int x = 8; x <= 12; x++)
        {
            for (int y = 5; y < 32; y++) { flags[x][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        }
        flags[9][23] = 0; flags[11][23] = 0;
        when(collision.getFlags()).thenReturn(flags);
        WorldPoint west = new WorldPoint(1627, 4023, 0), east = new WorldPoint(1633, 4023, 0);
        when(player.getWorldLocation()).thenReturn(west);
        LocalPoint westLocal = LocalPoint.fromScene(7, 23, view), eastLocal = LocalPoint.fromScene(13, 23, view);
        when(player.getLocalLocation()).thenReturn(westLocal);
        when(config.mode()).thenReturn(WintertodtMode.SOLO);
        when(client.getRealSkillLevel(Skill.AGILITY)).thenReturn(60);
        when(client.getBoostedSkillLevel(Skill.AGILITY)).thenReturn(60);
        WintertodtPathTracker tracker = new WintertodtPathTracker();
        TrackerTestSupport.inject(tracker, "client", client); TrackerTestSupport.inject(tracker, "config", config);
        tracker.update(east, null, null, true);
        assertEquals(java.util.Arrays.asList(west, new WorldPoint(1629, 4023, 0),
            new WorldPoint(1631, 4023, 0), east), tracker.getPath());
        when(client.getBoostedSkillLevel(Skill.AGILITY)).thenReturn(59);
        tracker.update(east, null, null, true);
        assertTrue(tracker.getPath().contains(new WorldPoint(1628, 4004, 0)));
        when(client.getBoostedSkillLevel(Skill.AGILITY)).thenReturn(60);
        when(client.getRealSkillLevel(Skill.AGILITY)).thenReturn(59);
        tracker.update(east, null, null, true);
        assertTrue(tracker.getPath().size() > 4);
        when(client.getRealSkillLevel(Skill.AGILITY)).thenReturn(60);
        when(config.mode()).thenReturn(WintertodtMode.MASS);
        tracker.update(east, null, null, true); assertTrue(tracker.getPath().size() > 4);
        when(config.mode()).thenReturn(WintertodtMode.SOLO);
        when(player.getWorldLocation()).thenReturn(east);
        when(player.getLocalLocation()).thenReturn(eastLocal);
        tracker.update(west, null, null, true);
        assertEquals(east, tracker.getPath().get(0)); assertEquals(4, tracker.getPath().size());
        assertEquals(west, tracker.getPath().get(3));
        flags[9][23] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        flags[11][23] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        tracker.invalidate(); tracker.update(west, null, null, true);
        assertEquals(4, tracker.getPath().size());
        flags[9][23] = 0x1000000; tracker.invalidate();
        tracker.update(west, null, null, true); assertTrue(tracker.getPath().size() > 4);
        tracker.update(west, null, null, false); assertTrue(tracker.getPath().isEmpty());
    }
}

package com.wintertodtautopilot;

import java.util.List;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Point;
import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtPathfinderTest
{
    @Test public void routesAroundWallThroughOnlyOpening()
    {
        int[][] flags = new int[7][7];
        for (int y = 0; y < 6; y++) { flags[3][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        List<Point> path = WintertodtPathfinder.find(flags, new Point(1, 1), 5, 1, 5, 1, false);
        assertFalse(path.isEmpty()); assertTrue(path.contains(new Point(3, 6)));
        for (int i = 1; i < path.size(); i++)
        {
            Point a = path.get(i-1), b = path.get(i);
            assertEquals(1, Math.max(Math.abs(a.getX()-b.getX()), Math.abs(a.getY()-b.getY())));
            assertTrue(WintertodtPathfinder.canStep(flags, a.getX(), a.getY(), b.getX(), b.getY()));
        }
    }
    @Test public void checksWallsOnBothSidesOfTileEdge()
    {
        int[][] flags = new int[2][1];
        flags[0][0] = CollisionDataFlag.BLOCK_MOVEMENT_EAST;
        assertTrue(WintertodtPathfinder.find(flags, new Point(0, 0), 1, 0, 1, 0, false).isEmpty());
        flags[0][0] = 0; flags[1][0] = CollisionDataFlag.BLOCK_MOVEMENT_WEST;
        assertTrue(WintertodtPathfinder.find(flags, new Point(0, 0), 1, 0, 1, 0, false).isEmpty());
    }
    @Test public void stopsBesideBlockedObjectFootprint()
    {
        int[][] flags = new int[8][8];
        for (int x = 4; x <= 6; x++) { for (int y = 4; y <= 6; y++) { flags[x][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; } }
        List<Point> path = WintertodtPathfinder.find(flags, new Point(0, 0), 4, 4, 6, 6, true);
        assertFalse(path.isEmpty());
        Point end = path.get(path.size()-1);
        assertTrue(end.getX() == 3 && end.getY() >= 4 && end.getY() <= 6
            || end.getY() == 3 && end.getX() >= 4 && end.getX() <= 6);
        assertEquals(0, flags[end.getX()][end.getY()]);
    }
    @Test public void unreachableOrUnloadedTilesHaveNoStraightLineFallback()
    {
        int[][] flags = new int[3][3];
        flags[1][0] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        flags[0][1] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        assertTrue(WintertodtPathfinder.find(flags, new Point(0, 0), 2, 2, 2, 2, false).isEmpty());
        assertTrue(WintertodtPathfinder.find(flags, new Point(0, 0), 5, 5, 5, 5, false).isEmpty());
        int[][] unloaded = new int[2][1]; unloaded[1][0] = 0x1000000;
        assertTrue(WintertodtPathfinder.find(unloaded, new Point(0, 0), 1, 0, 1, 0, false).isEmpty());
    }
    @Test public void prefersShortWalkOverSlowJumps()
    {
        java.util.List<Point> jumps = java.util.Arrays.asList(new Point(1, 1), new Point(3, 1));
        List<Point> path = WintertodtPathfinder.find(new int[5][3], new Point(0, 1), 4, 1, 4, 1, false, jumps);
        assertEquals(5, path.size());
        assertTrue(path.contains(new Point(2, 1)));
    }
    @Test public void crossesOpenGroundDiagonallyWithTheFewestTurns()
    {
        int[][] flags = new int[12][12];
        List<Point> diagonal = WintertodtPathfinder.find(flags, new Point(1, 1), 8, 8, 8, 8, false);
        assertEquals(8, diagonal.size());
        for (int i = 0; i < diagonal.size(); i++) { assertEquals(new Point(i + 1, i + 1), diagonal.get(i)); }
        List<Point> route = WintertodtPathfinder.find(flags, new Point(1, 1), 10, 6, 10, 6, false);
        assertEquals(10, route.size());
        int turns = 0, dx = 0, dy = 0;
        for (int i = 1; i < route.size(); i++)
        {
            int nextDx = route.get(i).getX() - route.get(i - 1).getX();
            int nextDy = route.get(i).getY() - route.get(i - 1).getY();
            if (i > 1 && (nextDx != dx || nextDy != dy)) { turns++; }
            dx = nextDx; dy = nextDy;
        }
        assertEquals(1, turns);
        assertEquals(route, WintertodtPathfinder.find(flags, new Point(1, 1), 10, 6, 10, 6, false));
    }

    @Test public void diagonalsRespectEveryCornerWallAndBlockedSideInAllDirections()
    {
        int[] dx = {1, -1, -1, 1}, dy = {1, 1, -1, -1};
        int[] corners = {CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST, CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST,
            CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST};
        for (int i = 0; i < 4; i++)
        {
            int nx = 1 + dx[i], ny = 1 + dy[i];
            int[][] flags = new int[3][3];
            assertTrue(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[1][1] = corners[i];
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[1][1] = 0; flags[nx][ny] = corners[(i + 2) % 4];
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[nx][ny] = 0; flags[nx][1] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[nx][1] = 0; flags[1][ny] = 0x1000000;
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[1][ny] = 0;
            flags[nx][1] = dy[i] > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH : CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
            flags[nx][1] = 0;
            flags[1][ny] = dx[i] > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_EAST : CollisionDataFlag.BLOCK_MOVEMENT_WEST;
            assertFalse(WintertodtPathfinder.canStep(flags, 1, 1, nx, ny));
        }
    }

}

package com.wintertodtautopilot;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtPauseTest
{
    @Test public void pausedTicksKeepObservationsButClearGuidanceAndMuteNotifications() throws Exception
    {
        WintertodtAutopilotPlugin plugin = new WintertodtAutopilotPlugin();
        Client client = mock(Client.class); Player player = mock(Player.class);
        ClientThread thread = mock(ClientThread.class);
        WintertodtStateTracker tracker = mock(WintertodtStateTracker.class);
        WintertodtHintArrow arrow = mock(WintertodtHintArrow.class);
        WintertodtPathTracker paths = mock(WintertodtPathTracker.class);
        Notifier notifier = mock(Notifier.class);
        TrackerTestSupport.inject(plugin, "client", client);
        TrackerTestSupport.inject(plugin, "configManager", mock(net.runelite.client.config.ConfigManager.class));
        TrackerTestSupport.inject(plugin, "clientThread", thread);
        TrackerTestSupport.inject(plugin, "tracker", tracker);
        TrackerTestSupport.inject(plugin, "arrow", arrow);
        TrackerTestSupport.inject(plugin, "paths", paths);
        TrackerTestSupport.inject(plugin, "notifier", notifier);
        boolean[] paused = {false};
        TrackerTestSupport.inject(plugin, "config", new WintertodtAutopilotConfig() {
            @Override public boolean pauseGuidance() { return paused[0]; }
        });
        ConfigChanged change = new ConfigChanged();
        change.setGroup("wintertodtautopilot"); change.setKey("pauseGuidance");
        TrackerTestSupport.inject(plugin, "bootstrapNeeded", false);
        doAnswer(call -> { call.getArgument(0, Runnable.class).run(); return null; }).when(thread).invoke(any(Runnable.class));
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getWorldLocation()).thenReturn(new WorldPoint(1639, 3997, 0));
        WintertodtSnapshot s = WintertodtSnapshot.builder().roundState(RoundState.ACTIVE).warmth(15)
            .warmthItem(1).points(100).workingCorner(WorkingCorner.SOUTHEAST).build();
        when(tracker.snapshot(any())).thenReturn(s);
        TrackerTestSupport.inject(plugin, "targetPoint", new WorldPoint(1638, 3997, 0));
        paused[0] = true; plugin.onConfigChanged(change); assertTrue(plugin.isPaused());
        // The settings event must clear existing cues before another game tick.
        assertNull(plugin.getTargetPoint());
        verify(arrow).clear(); verify(paths, atLeastOnce()).reset();
        plugin.onGameTick(new GameTick());
        assertEquals(s, plugin.getSnapshot());
        assertNotNull(plugin.getObjective()); assertNull(plugin.getTargetPoint());
        verify(arrow, atLeastOnce()).clear(); verify(paths, atLeastOnce()).reset();
        verifyNoInteractions(notifier);
        verify(arrow, never()).update(any(), any(), anyBoolean());
        paused[0] = false; plugin.onConfigChanged(change); assertFalse(plugin.isPaused());
        plugin.onGameTick(new GameTick());
        verify(notifier).notify("Wintertodt: low warmth - restore now");
        verify(arrow).update(null, null, true);
    }

    @Test public void visualSettingsClearOwnedCuesImmediatelyAndIgnoreOtherPlugins() throws Exception
    {
        WintertodtAutopilotPlugin plugin = new WintertodtAutopilotPlugin();
        ClientThread thread = mock(ClientThread.class);
        WintertodtHintArrow arrow = mock(WintertodtHintArrow.class);
        WintertodtPathTracker paths = mock(WintertodtPathTracker.class);
        TrackerTestSupport.inject(plugin, "clientThread", thread);
        TrackerTestSupport.inject(plugin, "arrow", arrow);
        TrackerTestSupport.inject(plugin, "paths", paths);
        TrackerTestSupport.inject(plugin, "config", new WintertodtAutopilotConfig() {
            @Override public boolean showHintArrow() { return false; }
            @Override public boolean showPath() { return false; }
            @Override public boolean highlightStandingTiles() { return false; }
        });
        doAnswer(call -> { call.getArgument(0, Runnable.class).run(); return null; })
            .when(thread).invoke(any(Runnable.class));
        ConfigChanged change = new ConfigChanged();
        change.setGroup("otherplugin"); change.setKey("showHintArrow");
        plugin.onConfigChanged(change);
        verifyNoInteractions(arrow, paths);
        change.setGroup("wintertodtautopilot");
        plugin.onConfigChanged(change);
        verify(arrow).clear(); verify(paths, atLeastOnce()).reset();
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtRoundForecastTest
{
    @Test public void learnsSustainedPaceAndKeepsAModerateSafetyMargin()
    {
        WintertodtRoundForecast forecast = new WintertodtRoundForecast();
        for (int tick = 0; tick < 30; tick++) { forecast.observe(30 - tick / 10, tick, 4); }
        assertEquals(-1, forecast.getSecondsLeft());
        forecast.observe(27, 30, 4);
        assertTrue(forecast.getSecondsLeft() >= 150 && forecast.getSecondsLeft() <= 190);
        assertEquals((int) (forecast.getSecondsLeft() * .9) - 3, forecast.getBudgetSeconds());
    }
    @Test public void respondsToSustainedAccelerationWithoutChasingOneDrop()
    {
        WintertodtRoundForecast forecast = new WintertodtRoundForecast();
        for (int tick = 0; tick <= 70; tick++) { forecast.observe(60 - tick / 10, tick, 4); }
        int before = forecast.getSecondsLeft();
        for (int tick = 71; tick <= 130; tick++) { forecast.observe(53 - (tick - 70) / 2, tick, 4); }
        assertTrue(forecast.getSecondsLeft() < before / 2);
        assertTrue(forecast.getSecondsLeft() < 70);
    }
    @Test public void partialBrazierChangesDoNotDiscardLearnedPace()
    {
        WintertodtRoundForecast forecast = new WintertodtRoundForecast();
        for (int tick = 0; tick <= 50; tick++) { forecast.observe(30 - tick / 10, tick, 4); }
        int before = forecast.getSecondsLeft();
        forecast.observe(25, 51, 3);
        assertTrue(forecast.getSecondsLeft() > 0);
        assertTrue(Math.abs(before - forecast.getSecondsLeft()) <= 2);
        forecast.observe(25, 52, 4);
        assertTrue(Math.abs(before - forecast.getSecondsLeft()) <= 2);
    }
    @Test public void unavailableAndStalledSignalsInvalidatePrediction()
    {
        WintertodtRoundForecast forecast = new WintertodtRoundForecast();
        for (int tick = 0; tick <= 50; tick++) { forecast.observe(30 - tick / 10, tick, 4); }
        forecast.observe(25, 71, 4);
        assertEquals(-1, forecast.getSecondsLeft());
        forecast.observe(25, 72, 0);
        assertEquals(-1, forecast.getSecondsLeft());
        forecast.observe(-1, 73, 4);
        assertEquals(-1, forecast.getBudgetSeconds());
    }
    @Test public void newRoundAndSingleHudBurstDoNotProduceFalseCountdown()
    {
        WintertodtRoundForecast forecast = new WintertodtRoundForecast();
        forecast.observe(30, 0, 4); forecast.observe(20, 30, 4);
        assertEquals(-1, forecast.getSecondsLeft());
        forecast.reset();
        for (int tick = 0; tick <= 50; tick++) { forecast.observe(30 - tick / 10, tick, 4); }
        assertTrue(forecast.getSecondsLeft() > 0);
        forecast.observe(100, 51, 4);
        assertEquals(-1, forecast.getSecondsLeft());
        forecast.observe(99, 71, 4);
        assertEquals(-1, forecast.getSecondsLeft());
    }
}

package com.wintertodtautopilot;

import net.runelite.api.Client;
