        tracker.select(WorkingCorner.SOUTHEAST.location(), WorkingCorner.AUTOMATIC, null); tracker.add(brazier);
        assertEquals(BrazierState.LIT, tracker.brazier(WorkingCorner.SOUTHEAST.location()));
        when(transformed.getId()).thenReturn(ObjectID.WINT_BRAZIER_BROKEN);
        assertEquals(BrazierState.BROKEN, tracker.brazier(WorkingCorner.SOUTHEAST.location()));
        tracker.remove(brazier);
        assertEquals(BrazierState.UNKNOWN, tracker.brazier(WorkingCorner.SOUTHEAST.location()));
    }
    @Test public void pyromancerUsesTransformedCompositionAndStaysLocal()
    {
        WintertodtNpcTracker tracker = new WintertodtNpcTracker();
        NPC npc = mock(NPC.class); NPCComposition transformed = mock(NPCComposition.class);
        when(npc.getId()).thenReturn(NpcID.WINT_WIZARD);
        when(npc.getTransformedComposition()).thenReturn(transformed);
        when(transformed.getId()).thenReturn(NpcID.WINT_WIZARD_DOWN);
        when(npc.getWorldLocation()).thenReturn(WorkingCorner.SOUTHWEST.location()); tracker.add(npc);
        assertEquals(NpcID.WINT_WIZARD_DOWN, WintertodtNpcTracker.id(npc));
        assertSame(npc, tracker.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location()));
        assertNull(tracker.target(TargetKind.PYROMANCER, WorkingCorner.NORTHEAST.location()));
        tracker.reset(); assertNull(tracker.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location()));
    }
    @Test public void fletchingArrivalUsesBrazierFootprintAndRejectsDiagonalTile() throws Exception
    {
        Client client = mock(Client.class); WorldView view = mock(WorldView.class);
        WintertodtObjectTracker tracker = new WintertodtObjectTracker();
        TrackerTestSupport.inject(tracker, "client", client);
        GameObject brazier = mock(GameObject.class); Player player = mock(Player.class);
        ObjectComposition definition = mock(ObjectComposition.class);
        when(brazier.getId()).thenReturn(ObjectID.WINT_BRAZIER_LIT);
        when(brazier.getWorldLocation()).thenReturn(WorkingCorner.SOUTHEAST.location());
        when(client.getObjectDefinition(ObjectID.WINT_BRAZIER_LIT)).thenReturn(definition);
        when(definition.getId()).thenReturn(ObjectID.WINT_BRAZIER_LIT);
        net.runelite.api.coords.LocalPoint objectTile = net.runelite.api.coords.LocalPoint.fromScene(20, 20, view);
        net.runelite.api.coords.LocalPoint adjacent = net.runelite.api.coords.LocalPoint.fromScene(22, 20, view);
        net.runelite.api.coords.LocalPoint diagonal = net.runelite.api.coords.LocalPoint.fromScene(22, 22, view);
        net.runelite.api.coords.LocalPoint distant = net.runelite.api.coords.LocalPoint.fromScene(30, 20, view);
        when(brazier.getLocalLocation()).thenReturn(objectTile);
        when(brazier.getSceneMinLocation()).thenReturn(new Point(20, 20));
        when(brazier.getSceneMaxLocation()).thenReturn(new Point(21, 21));
        when(player.getWorldLocation()).thenReturn(WorkingCorner.SOUTHEAST.location());
        tracker.select(WorkingCorner.SOUTHEAST.location(), WorkingCorner.SOUTHEAST, null);
        tracker.add(brazier);
        when(player.getLocalLocation()).thenReturn(adjacent);
        assertEquals(0, tracker.brazierDistance(player));
        when(player.getLocalLocation()).thenReturn(diagonal);
        assertEquals(1, tracker.brazierDistance(player));
        when(player.getLocalLocation()).thenReturn(distant);
        assertEquals(8, tracker.brazierDistance(player));
        tracker.remove(brazier);
        assertEquals(-1, tracker.brazierDistance(player));
    }

    @Test public void cornerObservationResolvesRemoteBraziersWithoutChangingWorkingTarget() throws Exception
    {
        Client client = mock(Client.class);
        WintertodtObjectTracker tracker = new WintertodtObjectTracker();
        TrackerTestSupport.inject(tracker, "client", client);
        for (WorkingCorner corner : WorkingCorner.values())
        {
            if (corner == WorkingCorner.AUTOMATIC) { continue; }
            GameObject object = mock(GameObject.class);
            int id = corner == WorkingCorner.NORTHEAST ? ObjectID.WINT_BRAZIER_LIT : ObjectID.WINT_BRAZIER;
            when(object.getId()).thenReturn(id);
            when(object.getWorldLocation()).thenReturn(corner.location());
            ObjectComposition definition = mock(ObjectComposition.class);
            when(client.getObjectDefinition(id)).thenReturn(definition);
            when(definition.getId()).thenReturn(id);
            tracker.add(object);
        }
        tracker.select(WorkingCorner.SOUTHWEST.location(), WorkingCorner.SOUTHWEST, null);
        assertEquals(BrazierState.LIT, tracker.brazierAt(WorkingCorner.NORTHEAST));
        assertEquals(BrazierState.UNLIT, tracker.brazierAt(WorkingCorner.SOUTHWEST));
        assertEquals(WorkingCorner.SOUTHWEST.location(), tracker.target(TargetKind.BRAZIER,
            WorkingCorner.NORTHEAST.location()).getWorldLocation());
        assertEquals(BrazierState.UNKNOWN, tracker.brazierAt(WorkingCorner.AUTOMATIC));
        tracker.reset();
        assertEquals(BrazierState.UNKNOWN, tracker.brazierAt(WorkingCorner.NORTHEAST));
    }

}

package com.wintertodtautopilot;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.mockito.Mockito.*;

public class WintertodtUpdateNoticeTest
{
    @Test public void waitsForLoginAndPersistsAcrossTicksAndPluginRestarts() throws Exception
    {
        Client client = mock(Client.class);
        ConfigManager manager = mock(ConfigManager.class);
        Map<String, String> saved = new HashMap<>();
        when(manager.getConfiguration("wintertodtautopilot", WintertodtAutopilotPlugin.UPDATE_NOTICE_KEY))
            .thenAnswer(call -> saved.get("notice"));
        doAnswer(call -> { saved.put("notice", call.getArgument(2)); return null; }).when(manager)
            .setConfiguration(eq("wintertodtautopilot"), eq(WintertodtAutopilotPlugin.UPDATE_NOTICE_KEY), anyString());
        WintertodtAutopilotPlugin plugin = plugin(client, manager);
        when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
        plugin.onGameTick(new GameTick());
        verifyNoInteractions(manager);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        plugin.onGameTick(new GameTick());
        plugin.onGameTick(new GameTick());
        when(client.getGameState()).thenReturn(GameState.HOPPING);
        plugin.onGameTick(new GameTick());
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        plugin(client, manager).onGameTick(new GameTick());
        verify(client, times(1)).addChatMessage(ChatMessageType.GAMEMESSAGE, "", WintertodtAutopilotPlugin.UPDATE_NOTICE, null);
        verify(manager, times(1)).setConfiguration("wintertodtautopilot", WintertodtAutopilotPlugin.UPDATE_NOTICE_KEY,
            WintertodtAutopilotPlugin.UPDATE_NOTICE_VERSION);
        // A separate RuneLite profile has its own saved configuration.
        saved.clear();
        plugin.onGameTick(new GameTick());
        verify(client, times(2)).addChatMessage(ChatMessageType.GAMEMESSAGE, "", WintertodtAutopilotPlugin.UPDATE_NOTICE, null);
    }

    @Test public void olderNoticeMarkerStillReceivesThisUpdate() throws Exception
    {
        Client client = mock(Client.class);
        ConfigManager manager = mock(ConfigManager.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(manager.getConfiguration("wintertodtautopilot", WintertodtAutopilotPlugin.UPDATE_NOTICE_KEY)).thenReturn("0.2.0");
        plugin(client, manager).onGameTick(new GameTick());
        verify(client).addChatMessage(ChatMessageType.GAMEMESSAGE, "", WintertodtAutopilotPlugin.UPDATE_NOTICE, null);
    }

    private WintertodtAutopilotPlugin plugin(Client client, ConfigManager manager) throws Exception
    {
        WintertodtAutopilotPlugin plugin = new WintertodtAutopilotPlugin();
        TrackerTestSupport.inject(plugin, "client", client);
        TrackerTestSupport.inject(plugin, "configManager", manager);
        // No player, region, or gameplay-guidance dependencies: the notice works anywhere, even paused.
        return plugin;
    }
}
